Object.assign(window.TEM8_DICTIONARY, {"vast":{"media":{"uk":"media/uk/vast__gb_1.mp3","us":"media/us/vast__us_1.mp3"},"oxford":{"phon":"vɑːst","pos":"adjective","senses":[{"en":"extremely large in area, size, amount, etc.","cn":"辽阔的；巨大的；庞大的；大量的","ex":{"en":"a vast area of forest","cn":"莽莽苍苍的森林"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巨大的;广大的;广阔的","en":"Something that is vast is extremely large.","ex":{"en":"...Afrikaner farmers who own vast stretches of land","cn":"拥有广袤土地的南非白人农场主"}}]},"examples":[{"en":"In the vast majority of cases, this should not be a problem.","cn":"在绝大多数情况下，这应该不成问题。"},{"en":"At dusk bats appear in vast numbers.","cn":"蝙蝠于傍晚时分大批出现。"}]},"vacation":{"oxford":{"phon":"veɪˈkeɪʃn","pos":"noun","senses":[{"en":"a period of time spent travelling or resting away from home","cn":"度假","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"They're on vacation in Hawaii right now.","cn":"他们此时正在夏威夷度假。"}},{"en":"(in the UK) one of the periods of time when universities or courts of law are closed; (in the US) one of the periods of time when schools, colleges, universities or courts of law are closed","cn":"（英国大学的）假期；（美国学校的）假期；（法庭的）休庭期","g":"[countable]","lab":"British English","ex":{"en":"the Christmas/Easter/summer vacation","cn":"圣诞节／复活节假期；暑假"}},{"en":"to spend a holiday somewhere","cn":"度假；休假","ex":{"en":"They are currently vacationing in Florida.","cn":"他们目前正在佛罗里达度假。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（大学或美国大中小学的）假期","en":"A vacation is a period of the year when universities and colleges, and in the United States also schools, are officially closed.","ex":{"en":"During his summer vacation he visited Russia","cn":"暑假期间他去俄罗斯了。"}},{"pos":"N-COUNT 可数名词","cn":"假日;休假","en":"A vacation is a period of time during which you relax and enjoy yourself away from home.","ex":{"en":"They planned a late summer vacation in Europe","cn":"他们打算夏末去欧洲度假。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"休息日;假期","en":"If you have a particular number of days' or weeks' vacation, you do not have to go to work for that number of days or weeks.","ex":{"en":"The French get five to six weeks' vacation a year.","cn":"法国人每年有5到6周的假期。"}},{"pos":"VERB 动词","cn":"（离家在某地）度假","en":"If you are vacationing in a place away from home, you are on vacation there.","ex":{"en":"Myles vacationed in Jamaica","cn":"迈尔斯去了牙买加度假。"}}]},"media":{"uk":"media/uk/vacation__gb_1.mp3","us":"media/us/vacation__us_1.mp3"},"examples":[{"en":"The job includes two weeks' paid vacation.","cn":"这份工作包括两周的带薪假期。"},{"en":"They are currently vacationing in Florida.","cn":"他们目前正在佛罗里达州度假。"}]},"vastly":{"media":{"uk":"media/uk/vastly__gb_1.mp3","us":"media/us/vastly__us_1.mp3"},"oxford":{"phon":"ˈvɑːstli","pos":"adverb","senses":[{"en":"very much","cn":"非常；很","ex":{"en":"I'm a vastly different person now.","cn":"我现在已判若两人了。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"很大程度上;极大地","en":"Vastly means to an extremely great degree or extent.","ex":{"en":"The jury has heard two vastly different accounts of what happened.","cn":"陪审团听到了对所发生事件的两种截然不同的陈述。"}}]},"examples":[{"en":"The quality of the training has vastly improved.","cn":"训练的质量已经大幅度提高。"},{"en":"I'm a vastly different person now.","cn":"我现在已判若两人了。"}]},"valley":{"media":{"uk":"media/uk/valley__gb_1.mp3","us":"media/us/valley__us_1.mp3"},"oxford":{"phon":"ˈvæli","pos":"noun","senses":[{"en":"an area of low land between hills or mountains, often with a river flowing through it; the land that a river flows through","cn":"谷；山谷；溪谷；流域","ex":{"en":"In the valley below cows were grazing peacefully.","cn":"牛群在下面的山谷里安静地吃着青草。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山谷;（尤指）溪谷","en":"A valley is a low stretch of land between hills, especially one that has a river flowing through it.","ex":{"en":"...a wooded valley set against the backdrop of Monte Rosa.","cn":"罗莎峰背后树木繁茂的山谷"}}]},"examples":[{"en":"a small town set in a valley","cn":"坐落在溪谷中的小镇"},{"en":"a wooded valley","cn":"树木茂盛的山谷"}]},"various":{"media":{"uk":"media/uk/various__gb_1.mp3","us":"media/us/various__us_1.mp3"},"oxford":{"phon":"ˈveəriəs","pos":"adjective","senses":[{"en":"several different","cn":"各种不同的；各种各样的","g":"[usually before noun]","lab":"formal","ex":{"en":"various types/forms/kinds of somebody/something","cn":"各色人等；各类事物"}},{"en":"having many different features","cn":"具有多种特征的；多姿多彩的","lab":"formal","ex":{"en":"a large and various country","cn":"一个多姿多彩的大国"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"各种各样的;不同种类的","en":"If you say that there are various things, you mean there are several different things of the type mentioned.","ex":{"en":"His plan is to spread the capital between various building society accounts","cn":"他打算把资金分散存到不同的购房互助会的账户上。"}},{"pos":"ADJ 形容词","cn":"迥异的;千差万别的","en":"If a number of things are described as various, they are very different from one another.","ex":{"en":"The methods are many and various.","cn":"方法很多且各不相同。"}}]},"examples":[{"en":"She took the job for various reasons.","cn":"她由于种种原因接受了这份工作。"},{"en":"Tents come in various shapes and sizes.","cn":"帐篷有各种各样的形状和大小。"}]},"vary":{"media":{"uk":"media/uk/vary__gb_1.mp3","us":"media/us/vary__us_1.mp3"},"oxford":{"phon":"ˈveəri","pos":"verb","senses":[{"en":"to be different from each other in size, shape, etc.","cn":"（大小、形状等）相异，不同，有别","g":"[intransitive]","ex":{"en":"New techniques were introduced with varying degrees of success.","cn":"引进新技术的成功程度不尽相同。"}},{"en":"to change or be different according to the situation","cn":"（根据情况）变化，变更，改变","g":"[intransitive]","ex":{"en":"The menu varies with the season.","cn":"菜单随季节而变动。"}},{"en":"to make changes to something to make it slightly different","cn":"（略为）变更，改变","g":"[transitive]","ex":{"en":"The job enables me to vary the hours I work.","cn":"这份工作使我能够调整工作时间。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"不同;有差异","en":"If things vary, they are different from each other in size, amount, or degree.","ex":{"en":"As they're handmade, each one varies slightly","cn":"由于它们是手工制作的，彼此都会有些微小的差异。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）变化;改变","en":"If something varies or if you vary it, it becomes different or changed.","ex":{"en":"The cost of the alcohol duty varies according to the amount of wine in the bottle","cn":"酒税税额随酒瓶容量的大小而有所不同。"}}]},"examples":[{"en":"Class numbers vary between 25 and 30.","cn":"班级的数目从 25 到 30 不等。"},{"en":"‘What time do you start work?’ ‘ It varies. ’ “","cn":"你几点钟开始工作？” “没准儿。”"}]},"variations":{"oxford":{"phon":"ˌveəriˈeɪʃn","pos":"noun","senses":[{"en":"a change, especially in the amount or level of sth （","cn":"数量、水平等的）变化，变更，变异"},{"en":"a thing that is different from other things in the same general group","cn":"变异的东西；变种；变体"}]}},"vaccine":{"oxford":{"phon":"ˈvæksiːn","pos":"noun","senses":[{"en":"a substance that is put into the blood and that protects the body from a disease","cn":"疫苗","ex":{"en":"a measles vaccine","cn":"麻疹疫苗"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"疫苗","en":"A vaccine is a substance containing a harmless form of the germs that cause a particular disease. It is given to people, usually by injection, to prevent them getting that disease.","ex":{"en":"Anti-malarial vaccines are now undergoing trials","cn":"抗疟疾的疫苗正在试验阶段。"}}]},"media":{"uk":"media/uk/vaccine__gb_1.mp3","us":"media/us/vaccine__us_1.mp3"},"examples":[{"en":"There is no vaccine against HIV infection.","cn":"现在还没有防止感染艾滋病病毒的疫苗。"},{"en":"a measles vaccine","cn":"麻疹疫苗"}]},"variable":{"oxford":{"phon":"ˈveəriəbl","pos":"noun","senses":[{"en":"a situation, number or quantity that can vary or be varied","cn":"可变情况；变量；可变因素","ex":{"en":"With so many variables, it is difficult to calculate the cost.","cn":"有这么多的可变因素，很难计算出成本。"}},{"en":"often changing; likely to change","cn":"多变的；易变的；变化无常的","ex":{"en":"variable temperatures","cn":"变化不定的气温"},"pos":"adjective"},{"en":"able to be changed","cn":"可更改的；可变的","ex":{"en":"The drill has variable speed control.","cn":"这台钻机有变速控制。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多变的;易变的;反复无常的","en":"Something that is variable changes quite often, and there usually seems to be no fixed pattern to these changes.","ex":{"en":"The potassium content of foodstuffs is very variable","cn":"食物中钾的含量差别很大。"}},{"pos":"N-COUNT 可数名词","cn":"（质量、数量、规模等）可变因素","en":"A variable is a factor that can change in quality, quantity, or size, which you have to take into account in a situation.","ex":{"en":"Decisions could be made on the basis of price, delivery dates, after-sales service or any other variable","cn":"购买决定可能会基于价格、送货日期、售后服务以及其他可变因素。"}},{"pos":"N-COUNT 可数名词","cn":"变量;变项;变元","en":"A variable is a quantity that can have any one of a set of values.","ex":{"en":"It is conventional to place the independent variable on the right-hand side of an equation.","cn":"普遍做法是把自变量放在等式的右边。"}}]},"media":{"uk":"media/uk/variable__gb_1.mp3","us":"media/us/variable__us_1.mp3"},"examples":[{"en":"With so many variables, it is difficult to calculate the cost.","cn":"有这么多的可变因素，很难计算出成本。"},{"en":"The temperature remained constant while pressure was a variable in the experiment.","cn":"做这实验时温度保持不变，但压力可变。"}]},"vaguely":{"media":{"uk":"media/uk/vaguely__gb_1.mp3","us":"media/us/vaguely__us_1.mp3"},"oxford":{"phon":"ˈveɪɡli","pos":"adverb","senses":[{"en":"in a way that is not detailed or exact","cn":"不详细地；含糊地；不确切地","ex":{"en":"a vaguely worded statement","cn":"措辞含糊的声明"}},{"en":"slightly","cn":"略微；稍微","ex":{"en":"There was something vaguely familiar about her face.","cn":"她有点儿面熟。"}},{"en":"in a way that shows that you are not paying attention or thinking clearly","cn":"心不在焉地","ex":{"en":"He smiled vaguely, ignoring her questions.","cn":"他漫不经心地笑了笑，没有理会她的问题。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"轻微地;有点儿","en":"Vaguely means to some degree but not to a very large degree.","ex":{"en":"The voice on the line was vaguely familiar, but Crook couldn't place it at first","cn":"电话里的声音有点儿熟悉，但是克鲁克一开始想不起来到底是谁。"}}]},"examples":[{"en":"He smiled vaguely, ignoring her questions.","cn":"他漫不经心地笑了笑，没有理会她的问题。"},{"en":"I can vaguely remember my first day at school.","cn":"我还依稀记得我第一天上学的情景。"}]},"varied":{"media":{"uk":"media/uk/varied__gb_1.mp3","us":"media/us/varied__us_1.mp3"},"oxford":{"phon":"ˈveərid","pos":"adjective","senses":[{"en":"of many different types","cn":"各种各样的；形形色色的；不相同的","ex":{"en":"varied opinions","cn":"各种不同的意见"}},{"en":"not staying the same, but changing often","cn":"变化的；多变的；不同的","ex":{"en":"He led a full and varied life.","cn":"他过着丰富多彩的生活。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多种多样的;形形色色的","en":"Something that is varied consists of things of different types, sizes, or qualities.","ex":{"en":"It is essential that your diet is varied and balanced","cn":"关键是你的饮食要多样化，并保持均衡。"}}]},"examples":[{"en":"a wide and varied selection of cheeses","cn":"种类繁多的可供选购的奶酪"},{"en":"He led a full and varied life.","cn":"他过着丰富多彩的生活。"}]},"variety":{"media":{"uk":"media/uk/variety__gb_1.mp3","us":"media/us/variety__us_1.mp3"},"oxford":{"phon":"vəˈraɪəti","pos":"noun","senses":[{"en":"several different sorts of the same thing","cn":"（同一事物的）不同种类，多种式样","g":"[singular + singular or plural verb]","ex":{"en":"There is a wide variety of patterns to choose from.","cn":"有种类繁多的图案可供选择。"}},{"en":"the quality of not being the same or not doing the same thing all the time","cn":"变化；多样化；多变性","g":"[uncountable]","ex":{"en":"It's the variety that makes my job so enjoyable.","cn":"我的工作丰富多彩，所以才有意思。"}},{"en":"a type of a thing, for example a plant or language, that is different from the others in the same general group","cn":"（植物、语言等的）变种，变体；异体；品种","g":"[countable]","ex":{"en":"Apples come in a great many varieties.","cn":"苹果的品种繁多。"}},{"en":"a form of theatre or television entertainment that consists of a series of short performances, such as singing, dancing and funny acts","cn":"综艺节目","g":"[uncountable]","lab":"North American English also","ex":{"en":"a variety show/theatre","cn":"综艺节目／剧场"}},{"en":"a US newspaper of the entertainment industry, published each week in New York. It includes reviews of plays, films, etc. and special articles about the entertainment world, and is known for its original and informal style of language. It was first published in 1905. From 1933 to 2013 there was a daily edition based in Los Angeles called Daily Variety. Its website features entertainment news, videos and photos.","cn":"种类：美国娱乐业报纸，每周在纽约发行。它包括戏剧，电影等的评论以及有关娱乐世界的特殊文章，并且以其原始和非正式的语言风格而闻名。它于1905年首次出版。从1933年到2013年，洛杉矶有一个日报，名为Daily Daily Variety。它的网站上有娱乐新闻，视频和照片。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"变化;多样化","en":"If something has variety, it consists of things which are different from each other.","ex":{"en":"Susan's idea of freedom was to have variety in her life style","cn":"苏珊心目中的自由就是拥有丰富多彩的生活。"}},{"pos":"N-SING 单数名词","cn":"各式各样;多种多样","en":"A variety of things is a number of different kinds or examples of the same thing.","ex":{"en":"West Hampstead has a variety of good shops and supermarkets","cn":"西汉普斯特德有各种各样不错的店铺和超级市场。"}},{"pos":"N-COUNT 可数名词","cn":"品种;种类","en":"A variety of something is a type of it.","ex":{"en":"I'm always pleased to try out a new variety","cn":"我一直乐于尝试新产品。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"综艺表演;综艺节目","en":"Variety is a type of entertainment which includes many different kinds of acts in the same show.","ex":{"en":"...a variety show of music, comedy, and magic.","cn":"汇集了音乐、喜剧及魔术表演的一档综艺节目"}}]},"examples":[{"en":"My cooking is of the ‘quick and simple’ variety.","cn":"我做饭菜属于既快捷又简单的那一类。"},{"en":"We want more variety in our work.","cn":"我们希望我们的工作多变点儿花样。"}]},"validation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a piece of new information confirms an idea or belief that people already have, it shows that it is definitely true","cn":""},{"en":"to show that something is definitely true by providing facts","cn":""}]},"examples":[{"en":"The Supreme Court has validated the lower court’s interpretation of the law.","cn":"","src":"ld"},{"en":"Many scientists plan to wait until the results of the study are validated by future research.","cn":"","src":"ld"}],"media":{"uk":"media/uk/validation__gb_1.mp3","us":"media/us/validation__us_1.mp3"},"oxford":{"phon":"ˌvælɪˈdeɪʃn","pos":"noun","senses":[{"en":"the act of proving that something is true or correct","cn":"证实；确认；确证","g":"[uncountable, countable]","ex":{"en":"There must be some form of external validation of the data.","cn":"必须对数据进行某种形式的外部验证。"}},{"en":"the act of making something legally recognized","cn":"验证：做出合法认可的行为","g":"[uncountable, countable]","ex":{"en":"validation of web service contracts","cn":"Web 服务合同的验证"}},{"en":"the act of stating officially that something is useful and of an acceptable standard","cn":"批准；确认…有效；认可","g":"[uncountable, countable]","ex":{"en":"an agreement on the validation of the institution's degree courses","cn":"关于机构学位课程验证的协议"}},{"en":"the feeling that others recognize that you are right or good enough","cn":"验证：他人认识到您是正确的或足够好的感觉","g":"[uncountable]","ex":{"en":"We seek validation from our peers.","cn":"我们寻求同行的认可。"}}]}},"variation":{"oxford":{"phon":"ˌveəriˈeɪʃn","pos":"noun","senses":[{"en":"a change, especially in the amount or level of something","cn":"（数量、水平等的）变化，变更，变异","g":"[countable, uncountable]","ex":{"en":"The dial records very slight variations in pressure.","cn":"该刻度盘能显示很微小的压力变化。"}},{"en":"a thing that is different from other things in the same general group","cn":"变异的东西；变种；变体","g":"[countable]","ex":{"en":"This soup is a spicy variation on a traditional favourite.","cn":"这种汤是在一种受欢迎的传统汤羹中加了香料。"}},{"en":"any of a set of short pieces of music based on a simple tune repeated in a different and more complicated form","cn":"变奏；变奏曲","g":"[countable]","lab":"music","ex":{"en":"a set of variations on a theme by Mozart","cn":"以莫扎特某一乐曲为主题的一组变奏曲"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（同一事物略微的）变化形式","en":"A variation on something is the same thing presented in a slightly different form.","ex":{"en":"This delicious variation on an omelette is quick and easy to prepare","cn":"这种稍加变化的可口煎蛋卷做起来又快又容易。"}},{"pos":"N-VAR 可变名词","cn":"（等级或数量的）变化，变动，变更","en":"A variation is a change or slight difference in a level, amount, or quantity.","ex":{"en":"The survey found a wide variation in the prices charged for canteen food","cn":"调查发现食堂饭菜的价格相差很大。"}}]},"media":{"uk":"media/uk/variation__gb_1.mp3","us":"media/us/variation__us_1.mp3"},"examples":[{"en":"This soup is a spicy variation on a traditional favourite.","cn":"这种汤是在一种受欢迎的传统汤羹中加了香料。"},{"en":"( figurative ) His numerous complaints are all variations on a theme (= all about the same thing).","cn":"他的满腹牢骚说来道去都是为了一件事。"}]},"valid":{"oxford":{"phon":"ˈvælɪd","pos":"adjective","senses":[{"en":"that is legally or officially acceptable","cn":"（法律上）有效的；（正式）认可的","ex":{"en":"Do you have a valid passport?","cn":"你有有效护照吗？"}},{"en":"based on what is logical or true","cn":"符合逻辑的；合理的；有根据的；确凿的","ex":{"en":"She had valid reasons for not supporting the proposals.","cn":"她有充分的理由不支持这些建议。"}},{"en":"that is accepted by the system","cn":"有效的；系统认可的","lab":"computing","ex":{"en":"a valid password","cn":"有效密码"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有根据的;正当的;合理的","en":"A valid argument, comment, or idea is based on sensible reasoning.","ex":{"en":"They put forward many valid reasons for not exporting","cn":"他们提出了很多不出口的正当理由。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有意义的;有效的","en":"Something that is valid is important or serious enough to make it worth saying or doing.","ex":{"en":"Most designers share the unspoken belief that fashion is a valid form of visual art.","cn":"大多数设计者都认同这样一种不言而明的理念，即时尚是视觉艺术的一种重要形式。"}},{"pos":"ADJ 形容词","cn":"（票证等）有效的","en":"If a ticket or other document is valid, it can be used and will be accepted by people in authority.","ex":{"en":"For foreign holidays you will need a valid passport","cn":"出国度假需持有效护照。"}}]},"media":{"uk":"media/uk/valid__gb_1.mp3","us":"media/us/valid__us_1.mp3"},"examples":[{"en":"She had valid reasons for not supporting the proposals.","cn":"她有充分的理由不支持这些建议。"},{"en":"The contract had been validly drawn up.","cn":"这份合同已依据法律草拟妥当。"}]},"valuable":{"media":{"uk":"media/uk/valuable__gb_1.mp3","us":"media/us/valuable__us_1.mp3"},"oxford":{"phon":"ˈvæljuəbl","pos":"adjective","senses":[{"en":"worth a lot of money","cn":"很值钱的；贵重的","ex":{"en":"My home is my most valuable asset.","cn":"房子是我最值钱的财产。"}},{"en":"very useful or important","cn":"很有用的；很重要的；宝贵的","ex":{"en":"a valuable experience/lesson","cn":"宝贵的经验／教训"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有价值的;有益的;有用的","en":"If you describe something or someone as valuable, you mean that they are very useful and helpful","ex":{"en":"Many of our teachers also have valuable academic links with Heidelberg University","cn":"我们的很多老师也和海德堡大学保持着有益的学术联系。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贵重的;值钱的","en":"Valuable objects are objects which are worth a lot of money.","ex":{"en":"Just because a camera is old does not mean it is valuable.","cn":"古旧的相机不一定就值钱。"}}]},"examples":[{"en":"The book provides valuable information on recent trends.","cn":"此书就近来的发展趋势提供了宝贵的信息。"},{"en":"a precious Chinese vase, valued at half a million pounds","cn":"价值 50 万英镑的稀世中国花瓶"}]},"vague":{"media":{"uk":"media/uk/vague__gb_1.mp3","us":"media/us/vague__us_1.mp3"},"oxford":{"phon":"veɪɡ","pos":"adjective","senses":[{"en":"not clear in a person’s mind","cn":"（思想上）不清楚的，含糊的，不明确的，模糊的","ex":{"en":"to have a vague impression/memory/recollection of something","cn":"对某事印象／记忆模糊"}},{"en":"not having or giving enough information or details about something","cn":"不具体的；不详细的；粗略的","ex":{"en":"She's a little vague about her plans for next year.","cn":"她对她明年的计划还不太确定。"}},{"en":"suggesting a lack of clear thought or attention","cn":"茫然的；糊涂的；心不在焉的","ex":{"en":"His vague manner concealed a brilliant mind.","cn":"他大智若愚。"}},{"en":"not having a clear shape","cn":"不清楚的；模糊的；朦胧的","ex":{"en":"In the darkness they could see the vague outline of a church.","cn":"他们在黑暗中能看到一座教堂的朦胧轮廓。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（文字或言语）含糊的，不明确的，不清楚的","en":"If something written or spoken is vague, it does not explain or express things clearly.","ex":{"en":"A lot of the talk was apparently vague and general","cn":"很多话明显是些含糊的泛泛之论。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（记忆或想法）模糊的，不清晰的","en":"If you have a vague memory or idea of something, the memory or idea is not clear.","ex":{"en":"They have only a vague idea of the amount of water available","cn":"他们只是大概知道可用水的总量。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含糊其词的;闪烁其词的","en":"If you are vague about something, you deliberately do not tell people much about it.","ex":{"en":"He was vague, however, about just what U.S. forces might actually do","cn":"然而，他对美军实际可能采取的行动却闪烁其词。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"思维不清的","en":"If you describe someone as vague, you mean that they do not seem to be thinking clearly.","ex":{"en":"She had married a charming but rather vague Englishman","cn":"她嫁给了一个外表迷人实际却很迷糊的英国人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（感觉等）轻微的，隐约的","en":"If something such as a feeling is vague, you experience it only slightly.","ex":{"en":"He was conscious of that vague feeling of irritation again","cn":"他再次感到有点儿恼火。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（外形或轮廓)模糊的，蒙眬的","en":"A vague shape or outline is not clear and is therefore not easy to see.","ex":{"en":"He looked at her vague shape through the frosted glass","cn":"他透过雾蒙蒙的眼镜注视着她模糊的身形。"}}]},"examples":[{"en":"In the darkness they could see the vague outline of a church.","cn":"他们在黑暗中能看到一座教堂的朦胧轮廓。"},{"en":"They had only a vague idea where the place was.","cn":"他们只是大概知道那个地方的位置。"}]},"vapour":{"oxford":{"phon":"ˈveɪpə(r)","pos":"noun","senses":[{"en":"a mass of very small drops of liquid in the air, for example steam","cn":"蒸气；潮气；雾气","ex":{"en":"water vapour","cn":"水蒸气"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"水汽;蒸汽;潮气","en":"Vapour consists of tiny drops of water or other liquids in the air, which appear as mist.","ex":{"en":"...water vapour.","cn":"水蒸气"}}]},"media":{"uk":"media/uk/vapour__gb_2.mp3","us":"media/us/vapour__us_2.mp3"},"examples":[{"en":"water vapour","cn":"水蒸气"}]},"van":{"media":{"img":["media/ldoce/img/van.jpg","media/pic/trucks_comp.jpg"],"uk":"media/uk/van__gb_1.mp3","us":"media/us/van__us_1.mp3"},"oxford":{"phon":"væn","pos":"noun","senses":[{"en":"a covered vehicle with no side windows in its back half, usually smaller than a lorry, used for carrying goods or people","cn":"客货车；厢式送货车","ex":{"en":"the driver of a white van","cn":"白色客货车的司机"}},{"en":"a covered vehicle with side windows, usually smaller than a lorry, that can carry about twelve passengers","cn":"面包车（通常为 12 座左右）","lab":"North American English"},{"en":"a closed coach on a train for carrying bags, cases, etc. or mail","cn":"（铁路上运送包裹、邮件等的）车厢","lab":"British English","ex":{"en":"a luggage van","cn":"装运行李的车厢"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（厢式）中小型货车;运货车","en":"A van is a small or medium-sized road vehicle with one row of seats at the front and a space for carrying goods behind."},{"pos":"N-COUNT 可数名词","cn":"（火车的）货车车厢，邮政车厢","en":"A van is a railway carriage, often without windows, which is used to carry luggage, goods, or mail.","ex":{"en":"In the guard's van lay my tin trunk.","cn":"我的铁皮箱放在了卫兵的行李车厢中。"}}]},"examples":[{"en":"a police van (= for carrying police officers or prisoners)","cn":"警车"},{"en":"a luggage van","cn":"装运行李的车厢"}]},"value":{"media":{"uk":"media/uk/value__gb_1.mp3","us":"media/us/value__us_1.mp3"},"oxford":{"phon":"ˈvæljuː","pos":"noun","senses":[{"en":"how much something is worth in money or other goods for which it can be exchanged","cn":"（商品）价值","g":"[uncountable, countable]","sc":"how much something is worth","ex":{"en":"to go up/rise/increase in value","cn":"升值"}},{"en":"how much something is worth compared with its price","cn":"（与价格相比的）值，划算程度","g":"[uncountable]","lab":"especially British English","sc":"how much something is worth","ex":{"en":"to be good/great value (= worth the money it costs)","cn":"很／极为合算"}},{"en":"the quality of being useful or important","cn":"用途；积极作用","g":"[uncountable, singular]","sc":"being useful/important","ex":{"en":"The value of regular exercise should not be underestimated.","cn":"经常锻炼的好处不应低估。"}},{"en":"beliefs about what is right and wrong and what is important in life","cn":"是非标准；生活准则；价值观","g":"[plural]","sc":"beliefs","ex":{"en":"We need to be guided by our moral values.","cn":"我们需要以道德观念为指导。"}},{"en":"the amount represented by a letter or symbol","cn":"值；数值","g":"[countable]","sc":"mathematics","ex":{"en":"Let y have the value 33.","cn":"假设 y 的值为 33。"}},{"en":"to think that somebody/something is important","cn":"重视；珍视","sc":"consider important","ex":{"en":"He has come to value her advice and support.","cn":"他开始重视她的建议和支持。"},"pos":"verb"},{"en":"to decide that something is worth a particular amount of money","cn":"给…估价；给…定价","g":"[usually passive]","sc":"decide worth","ex":{"en":"The property has been valued at over $2 million.","cn":"这处房地产估价为 200 多万美元。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"重要性;有用性;益处","en":"The value of something such as a quality, attitude, or method is its importance or usefulness. If you place a particular value on something, that is the importance or usefulness you think it has.","ex":{"en":"The value of this work experience should not be underestimated","cn":"这种工作经验的重要性不应该被低估。"}},{"pos":"VERB 动词","cn":"认为…重要;重视;珍视","en":"If you value something or someone, you think that they are important and you appreciate them.","ex":{"en":"I've done business with Mr Weston before. I value the work he gives me","cn":"我以前和韦斯顿先生有过业务往来，我很重视他给我的业务。"}},{"pos":"N-VAR 可变名词","cn":"价值","en":"The value of something is how much money it is worth.","ex":{"en":"The value of his investment has risen by more than $50,000","cn":"他投入的资本已经增值了5万多美元。"}},{"pos":"VERB 动词","cn":"给…估价;给…定价","en":"When experts value something, they decide how much money it is worth.","ex":{"en":"Your lender will then send their own surveyor to value the property","cn":"然后贷款方会派他们自己的评估员来对房产进行估价。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"等值;等价;物有所值","en":"You use value in certain expressions to say whether something is worth the money that it costs. For example, if something is or gives good value, it is worth the money that it costs.","ex":{"en":"The restaurant is informal, stylish and extremely good value","cn":"这家餐厅氛围轻松，装修雅致，而且价格非常公道。"}},{"pos":"N-PLURAL 复数名词","cn":"价值观;道德标准","en":"The values of a person or group are the moral principles and beliefs that they think are important.","ex":{"en":"The countries of South Asia also share many common values","cn":"南亚各国也有许多相同的价值观。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"重要特点，显著特点（用于其他名词后）","en":"Value is used after another noun when mentioning an important or noticeable feature about something.","ex":{"en":"The script has lost all of its shock value over the intervening 24 years","cn":"时隔24年后，这个剧本已经完全失去了震撼力。"}},{"pos":"N-COUNT 可数名词","cn":"（数）值","en":"A value is a particular number or quantity that can replace a symbol such as 'x' or 'y' in a mathematical expression."}]},"examples":[{"en":"The winner will receive a prize to the value of £1 000.","cn":"获胜者将得到价值为 1 000 英镑的奖项。"},{"en":"The young have a completely different set of values and expectations.","cn":"年轻人有一整套截然不同的价值观和期望。"}]},"validity":{"oxford":{"phon":"vəˈlɪdəti","pos":"noun","senses":[{"en":"the state of being legally or officially acceptable","cn":"（法律上的）有效，合法性；（正式的）认可","ex":{"en":"The period of validity of the agreement has expired.","cn":"本协议的有效期已过。"}},{"en":"the state of being logical and true","cn":"符合逻辑；正当；正确","ex":{"en":"We had doubts about the validity of their argument.","cn":"我们对他们的论点的正确性有过怀疑。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正当(性);正确(性)；可信(性)","en":"The validity of something such as a result or a piece of information is whether it can be trusted or believed.","ex":{"en":"Shocked by the results of the elections, they now want to challenge the validity of the vote","cn":"选举结果令他们很震惊，他们现在要对选举的可信性提出质疑。"}}]},"media":{"uk":"media/uk/validity__gb_1.mp3","us":"media/us/validity__us_1.mp3"},"examples":[{"en":"We had doubts about the validity of their argument.","cn":"我们对他们的论点的正确性有过怀疑。"},{"en":"The period of validity of the agreement has expired.","cn":"本协议的有效期已过。"}]},"vagina":{"oxford":{"phon":"vəˈdʒaɪnə","pos":"noun","senses":[{"en":"the passage in the body of a woman or female animal between the outer sex organs and the womb","cn":"阴道"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阴道","en":"A woman's vagina is the passage connecting her outer sex organs to her womb."}]},"media":{"uk":"media/uk/vagina__gb_1.mp3","us":"media/us/vagina__us_1.mp3"}},"valued":{"oxford":{"phon":"ˈvæljuː","pos":"noun","senses":[{"en":"how much sth is worth in money or other goods for which it can be exchanged （","cn":"商品）价值"},{"en":"( especially BrE ) how much sth is worth compared with its price （","cn":"与价格相比的）值，划算程度"}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdevalue.mp3","us":"media/ldoce/hwd/ame/e/value1.mp3"},"examples":[{"en":"Shelley valued her privacy.","cn":""},{"en":"Mr. Yeo valued Jan for her hard work.","cn":""}]},"vantage":{"oxford":{"phon":"ˈvɑːntɪdʒ pɔɪnt","pos":"noun","senses":[{"en":"a position from which you watch sth; a point in time or a situation from which you consider sth, especially the past （","cn":"观察事物的）有利地点；（尤指考虑旧时事物的）有利时刻，有利形势"}]}},"vases":{"oxford":{"phon":"vɑːz","pos":"noun","senses":[{"en":"a container made of glass, etc., used for holding cut flowers or as a decorative object","cn":"花瓶；装饰瓶"}]}},"values":{"oxford":{"phon":"ˈvæljuː","pos":"noun","senses":[{"en":"how much sth is worth in money or other goods for which it can be exchanged （","cn":"商品）价值"},{"en":"( especially BrE ) how much sth is worth compared with its price （","cn":"与价格相比的）值，划算程度"}]}},"varies":{"oxford":{"phon":"ˈveəri","pos":"verb","senses":[{"en":"to be different from each other in size, shape, etc. （","cn":"大小、形状等）相异，不同，有别"},{"en":"to change or be different according to the situation （","cn":"根据情况）变化，变更，改变"}]}},"vaccinations":{"oxford":{"phon":"ˈvæksɪneɪt","pos":"verb","senses":[{"en":"to give a person or an animal a vaccine , especially by injecting it, in order to protect them against a disease","cn":"给 … 接种疫苗"}]}},"valleys":{"oxford":{"phon":"ˈvæli","pos":"noun","senses":[{"en":"an area of low land between hills or mountains, often with a river flowing through it; the land that a river flows through","cn":"谷；山谷；溪谷；流域"}]}},"varieties":{"oxford":{"phon":"vəˈraɪəti","pos":"noun","senses":[{"en":"several different sorts of the same thing （","cn":"同一事物的）不同种类，多种式样"},{"en":"the quality of not being the same or not doing the same thing all the time","cn":"变化；多样化；多变性"}]}},"vanished":{"oxford":{"phon":"ˈvænɪʃ","pos":"verb","senses":[{"en":"to disappear suddenly and/or in a way that you cannot explain （","cn":"莫名其妙地）突然消失"},{"en":"to stop existing","cn":"不复存在；消亡；绝迹"}]}},"vasectomy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"输精管切除术","en":"A vasectomy is a surgical operation in which the tube that carries sperm to a man's penis is cut, usually as a means of contraception."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical operation to cut the small tube through which a man’s sperm passes so that he is unable to produce children","cn":"输精管切除术"}]},"media":{"uk":"media/ldoce/hwd/bre/7/vasectomy0205.mp3","us":"media/ldoce/hwd/ame/1/vasectomy.mp3"},"oxford":{"phon":"vəˈsektəmi","pos":"noun","senses":[{"en":"a medical operation to remove part of each of the tubes in a man’s body that carry sperm, after which he is not able to make a woman pregnant","cn":"输精管切除术","ex":{"en":"to have a vasectomy","cn":"进行输精管结扎术"}}]}},"variegated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（树叶或植物）杂色的，斑驳的","en":"A variegated leaf or plant has different colours on it.","ex":{"en":"The leaves are a variegated red.","cn":"这些树叶呈斑驳的红色。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多种多样的;形形色色的","en":"Something that is variegated consists of many different parts or types.","ex":{"en":"...our variegated dialects.","cn":"我们形形色色的方言"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a variegated plant, leaf etc has different coloured marks on it 〔","cn":"植物﹑叶子等〕杂色的﹐斑驳的"},{"en":"consisting of a lot of different types of thing","cn":"多样化的﹐形形色色的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something variegated has many different colors, as in the trees of autumn or the feathers of a peacock. Whenever you see \"vari\" at the beginning of a word, you know that the idea of difference or change is involved."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41variegated.mp3","us":"media/ldoce/hwd/ame/8/variegated.mp3"},"examples":[{"en":"a plant with variegated leaves","cn":"斑叶植物"},{"en":"variegated grasses","cn":"杂色的草"}],"oxford":{"phon":"ˈveəriəɡeɪtɪd","pos":"adjective","senses":[{"en":"having spots or marks of a different colour","cn":"斑驳的；有斑点的","lab":"specialist","ex":{"en":"a plant with variegated leaves","cn":"斑叶植物"}},{"en":"consisting of many different types of thing or person","cn":"五花八门的；形形色色的","lab":"formal"}]}},"vatican":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"梵蒂冈;天主教教皇（或教廷）","en":"The Vatican is the city state in Rome ruled by the Pope which is the centre of the Roman Catholic Church. You can also use the Vatican to refer to the Pope or his officials.","ex":{"en":"The president had an audience with the Pope in the Vatican","cn":"总统在梵蒂冈谒见了教皇。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the large palace in Rome where the Pope (= head of the Roman Catholic Church ) lives and works","cn":"梵蒂冈〔罗马教皇的宫廷〕"},{"en":"the government of the Pope","cn":"梵蒂冈〔指罗马教廷〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41vatican.mp3","us":"media/ldoce/hwd/ame/d/vatican.mp3"},"examples":[{"en":"The Vatican is taking a hard line on birth control.","cn":"梵蒂冈在节育的问题上立场强硬。"}]},"valiant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勇敢的;果决的;无畏的","en":"A valiant action is very brave and determined, though it may lead to failure or defeat.","ex":{"en":"Despite valiant efforts by the finance minister, inflation rose to 36%.","cn":"尽管财政部部长采取了一系列果决措施，通货膨胀率还是涨到了36%。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very brave, especially in a difficult situation 〔","cn":"尤指在困境中〕勇敢的﹐英勇的"}]},"vocab":{"pos":"adj","senses":[{"en":"It was pretty courageous of the automaker Plymouth to name a car the \"Valiant\" in the 1960s and 70s because that term usually refers to a hero or describes a really determined, or valiant, effort that doesn't end well."}]},"media":{"uk":"media/ldoce/hwd/bre/c/valiant0205.mp3","us":"media/ldoce/hwd/ame/4/valiant.mp3"},"examples":[{"en":"She made a valiant attempt not to laugh.","cn":"她试图强忍住不笑出来。"},{"en":"valiant warriors","cn":"勇敢的武士"}],"oxford":{"phon":"ˈvæliənt","pos":"adjective","senses":[{"en":"very brave or determined","cn":"英勇的；勇敢的；果敢的；坚定的","ex":{"en":"valiant warriors","cn":"勇敢的武士"}}]}},"vaporize":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）汽化;（使）蒸发","en":"If a liquid or solid vaporizes or if you vaporize it, it changes into vapour or gas.","ex":{"en":"The benzene vaporized and formed a huge cloud of gas","cn":"苯蒸发了,形成了一大团气体。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change into a vapour, or to make something, especially a liquid, do this (","cn":"使)蒸发﹐(使)汽化"}]},"vocab":{"pos":"v","senses":[{"en":"To vaporize is to evaporate and turn into gas. If you're watching a sci-fi movie, it probably means to vanish quickly or be utterly obliterated by a phaser gun."}]},"media":{"uk":"media/ldoce/hwd/bre/6/vaporize0205.mp3","us":"media/ldoce/hwd/ame/e/vaporize.mp3"},"oxford":{"phon":"ˈveɪpəraɪz","pos":"verb","senses":[{"en":"to turn into gas; to make something turn into gas","cn":"（使）汽化，蒸发"}]}},"vaccinate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"给…接种疫苗","en":"If a person or animal is vaccinated, they are given a vaccine, usually by injection, to prevent them from getting a disease.","ex":{"en":"Dogs must be vaccinated against distemper","cn":"狗必须接种犬瘟热疫苗。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to protect a person or animal from a disease by giving them a vaccine","cn":"给…接种疫苗﹐给…打预防针"}]},"vocab":{"pos":"v","senses":[{"en":"To vacciunate is to immunize someone against a disease. Babies are usually vaccinated against many diseases soon after birth."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vaccinate.mp3","us":"media/ldoce/hwd/ame/b/vaccinate.mp3"},"examples":[{"en":"Make sure your vaccinations are up to date.","cn":"一定要接种最新的疫苗。"},{"en":"I was vaccinated against tetanus.","cn":"我接种了破伤风疫苗。"}],"oxford":{"phon":"ˈvæksɪneɪt","pos":"verb","senses":[{"en":"to give a person or an animal a vaccine, especially by injecting it, in order to protect them against a disease","cn":"给…接种疫苗","lab":"British English","ex":{"en":"I was vaccinated against tetanus.","cn":"我接种了破伤风疫苗。"}}]}},"vandalise":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"vacuity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(思想的)贫乏,空洞,空虚","en":"If you refer to the vacuity of something or someone, you are critical of them because they lack intelligent thought or ideas.","ex":{"en":"His vacuity was a handicap in these debates.","cn":"在这些辩论中，思想贫乏是他的一个弱点。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"lack of intelligent, interesting, or serious thought","cn":"愚蠢﹔空虚﹔贫乏"}]},"vocab":{"pos":"n","senses":[{"en":"When you refer to something that is not there, you can refer to its vacuity . A stern teacher who is criticizing an empty-headed English essay might talk about its vacuity , or the absence of any real substance."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41vacuity.mp3","us":"media/ldoce/hwd/ame/f/vacuity.mp3"},"oxford":{"phon":"vəˈkjuːəti","pos":"noun","senses":[{"en":"lack of serious thought or purpose","cn":"空虚；茫然；缺乏思考"}]}},"varsity":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤用于修饰体育活动或体育比赛代表队）大学的","en":"People sometimes use varsity to describe things that relate to universities, especially sports activities or teams at a university or competitions between universities.","ex":{"en":"The school has not given them the same opportunities to participate in varsity sports that men receive.","cn":"学校没有给她们与男生同样多的参加大学体育活动的机会。"}},{"pos":"N-COUNT 可数名词","cn":"（学校的）校队，代表队","en":"The varsity is the main or first team for a particular sport at a high school, college, or university.","ex":{"en":"She has been in the playoffs every year since she made the varsity","cn":"自从加入校队后，她每年都能参加季后赛。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the main team that represents a university, college, or school in a sport 〔","cn":"体育比赛中的〕学校代表队﹐校队"},{"en":"a university, especially Oxford or Cambridge","cn":"大学〔尤指牛津大学或剑桥大学〕"}]},"vocab":{"pos":"n","senses":[{"en":"The word varsity identifies the starting team in a sport at a college or university. You have to be good to make varsity ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41varsity.mp3","us":"media/ldoce/hwd/ame/a/varsity.mp3"},"examples":[{"en":"She's still at varsity.","cn":"她还在上大学。"},{"en":"the varsity match","cn":"大学体育比赛"}],"oxford":{"phon":"ˈvɑːsəti","pos":"noun","senses":[{"en":"the main team that represents a college or high school, especially in sports competitions","cn":"（尤指体育比赛中大中学校的）代表队，校队","lab":"North American English","ex":{"en":"He made varsity as a wide receiver.","cn":"他进入校队担任外接手。"}},{"en":"university","cn":"大学","lab":"British English, old use or Indian English or South African English，，","ex":{"en":"She's still at varsity.","cn":"她还在上大学。"}},{"en":"used when describing activities connected with the universities of Oxford and Cambridge, especially sports competitions","cn":"（常用于牛津和剑桥两所大学的体育比赛）大学的","ex":{"en":"the varsity match","cn":"大学体育比赛"},"pos":"adjective"}]}},"vac":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（大学的）假期，寒暑假","en":"A vac is a period of the year when universities and colleges are officially closed. Vac is an abbreviation for (缩略=) 'vacation'.","ex":{"en":"...the summer vac.","cn":"暑假"}},{"pos":"N-COUNT 可数名词","cn":"真空吸尘器","en":"A vac is an electric machine which sucks up dust and dirt from carpets. Vac is an abbreviation for (缩略=) 'vacuum cleaner'.","ex":{"en":"We found the vac easy to push.","cn":"我们发现这种真空吸尘器很容易推着走。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a university vacation 1 (3) 〔","cn":"大学的〕假期"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vac.mp3","us":"media/ldoce/hwd/ame/2/laadvac.mp3"},"oxford":{"phon":"væk","pos":"noun","senses":[{"en":"a university vacation","cn":"（大学的）假期","ex":{"en":"the Christmas/Easter/summer vac","cn":"圣诞节/复活节/夏季假期"}}]}},"valueless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无价值的;无用的;无效的","en":"If you describe something as valueless, you mean that it is not at all useful.","ex":{"en":"Such attitudes are valueless unless they reflect inner cognition and certainty.","cn":"这种态度如果不能反映内心的认知和把握就毫无价值。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"worth no money or very little money","cn":"不值钱的"},{"en":"having no worth, importance, or good qualities","cn":"没有价值的﹔不重要的﹔质量差的"}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. completely, quite Our shares became completely valueless overnight.","PREP. as Some of the royal forests had become valueless as hunting grounds."]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41valueless.mp3","us":"media/ldoce/hwd/ame/5/laadvalueless.mp3"},"examples":[{"en":"On most political issues my own opinion was pretty well valueless.","cn":"在大多数政治问题上﹐我个人的观点很不重要。"},{"en":"valueless currency","cn":"不值钱的货币"}],"oxford":{"phon":"ˈvæljuːləs","pos":"adjective","senses":[{"en":"without value or worth","cn":"没有价值的；不值钱的","ex":{"en":"Her shares in the company have become valueless.","cn":"她在公司的股份已经变得毫无价值。"}}]}},"vapid":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乏味的;枯燥的;无趣的","en":"If you describe someone or something as vapid, you are critical of them because they are dull and uninteresting.","ex":{"en":"...the Minister's young and rather vapid wife","cn":"部长年轻无趣的妻子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lacking intelligence, interest, or imagination","cn":"缺少灵性的﹔乏味的﹔平庸的"}]},"vocab":{"pos":"adj","senses":[{"en":"Reserve the adjective vapid for the airhead in your office that brings nothing to the table, except maybe the doughnuts. Vapid is an adjective to describe someone or something that is dull or uninspiring."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41vapid.mp3","us":"media/ldoce/hwd/ame/1/vapid.mp3"},"examples":[{"en":"vapid conversation","cn":"平淡乏味的对话"}],"oxford":{"phon":"ˈvæpɪd","pos":"adjective","senses":[{"en":"not showing interest or intelligence","cn":"乏味的；枯燥的；愚蠢的","ex":{"en":"The vapid conversation bored her.","cn":"平淡的谈话让她感到厌烦。"}}]}},"vanilla":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"香草精;香子兰精","en":"Vanilla is a flavouring used in ice cream and other sweet food.","ex":{"en":"I added a dollop of vanilla ice-cream to the pie.","cn":"我在馅饼里加了一块香草冰激凌。"}},{"pos":"ADJ 形容词","cn":"寻常的;无特色的","en":"If you describe a person or thing as vanilla, you mean that they are ordinary, with no special or extra features.","ex":{"en":"...just plain vanilla couples like me and Tony","cn":"只是如我和托尼一样的平常夫妇"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used to give a special taste to ice cream , cakes etc, made from the beans of a tropical plant","cn":"香草精﹐香子兰精"},{"en":"having the taste of vanilla","cn":"香草味的"},{"en":"plain, ordinary, or uninteresting","cn":"寻常的﹐无特色的﹐乏味的"}]},"vocab":{"pos":"n adj","senses":[{"en":"Vanilla is the flavor for food — such as ice cream — that contains extract from the vanilla plant. This word also describes things that are boring or plain."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vanilla_adj0205.mp3","us":"media/ldoce/hwd/ame/c/vanilla1.mp3"},"examples":[{"en":"The city is pretty much plain vanilla.","cn":"这座城市相当一般化。"},{"en":"( BrE ) a vanilla pod","cn":"香子兰蒴果"}],"oxford":{"phon":"vəˈnɪlə","pos":"noun","senses":[{"en":"a substance obtained from the beans of a tropical plant, also called vanilla, used to add taste to sweet foods, for example ice cream","cn":"香草醛，香草香精（从热带植物香子兰豆中提取，用于冰激凌等甜食）","lab":"British English","ex":{"en":"vanilla essence","cn":"香子兰精"}},{"en":"tasting of vanilla","cn":"香子兰香味的；香草味的","ex":{"en":"vanilla ice cream","cn":"香草冰激凌"},"pos":"adjective"},{"en":"ordinary; not special in any way","cn":"普通的；寻常的；毫无特色的","lab":"informal","ex":{"en":"The city is pretty much plain vanilla.","cn":"这座城市相当一般化。"},"pos":"adjective"}]}},"vapor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of vapour vapour","cn":"的美式拼法"}]},"vocab":{"pos":"n","senses":[{"en":"When something that is normally liquid — like water — becomes a visible, gas-like substance floating in the air, it's a vapor ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41vapor.mp3","us":"media/ldoce/hwd/ame/4/vapor.mp3"},"oxford":{"phon":"ˈveɪpə(r)","pos":"noun","senses":[{"en":"a mass of very small drops of liquid in the air, for example steam","cn":"蒸气；潮气；雾气","ex":{"en":"water vapor","cn":"水汽"}}]}},"vainglorious":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非常自负的;自命不凡的","en":"If you describe someone as vainglorious, you are critical of them because they are very proud of what they have done and boast a lot about it."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too proud of your own abilities, importance etc","cn":"非常自负的﹐自命不凡的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you admire yourself in the mirror all the time and constantly brag about all the beauty contests you have won, you might rightfully get accused of being vainglorious ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/vainglorious0205.mp3","us":"media/ldoce/hwd/ame/f/laadvainglorious.mp3"},"oxford":{"phon":"ˌveɪnˈɡlɔːriəs","pos":"adjective","senses":[{"en":"too proud of your own abilities or achievements","cn":"自负的；自命不凡的；自吹自擂的"}]}},"vat":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"增值税","en":"VAT is a tax that is added to the price of goods or services. VAT is an abbreviation for (缩略=) 'value added tax'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large container for storing liquids in 〔","cn":"储存液体用的〕大缸﹐大桶﹐罐"}]},"vocab":{"pos":"n","senses":[{"en":"A vat is a big container for holding liquids. If you're having a big party, your mom may get you to help cook a vat of spaghetti sauce to feed all your hungry relatives."}]},"media":{"uk":"media/ldoce/hwd/bre/d/vat0703.mp3","us":"media/ldoce/hwd/ame/d/vat0703.mp3"},"examples":[{"en":"Prices include VAT.","cn":"价格中含增值税。"},{"en":"£27.50 + VAT * 27.50","cn":"英镑加增值税"}],"oxford":{"phon":"væt","pos":"noun","senses":[{"en":"a large container for holding liquids, especially in industrial processes","cn":"（尤指工业用）大桶，大盆，瓮，缸，罐","ex":{"en":"distilling vats","cn":"蒸馏罐"}},{"en":"a tax that is added to the price of goods and services (the abbreviation for ‘value added tax’)","cn":"增值税（全写为 value added tax）","ex":{"en":"Prices include VAT.","cn":"价格中含增值税。"}}]}},"valedictory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（致词、书信或演出）告别的，告别性质的","en":"A valedictory speech, letter, or performance is one that is intended as a way of saying goodbye when someone leaves another person, a place, or a job.","ex":{"en":"...Mr Walker, making his valedictory address after two years as chairman.","cn":"沃克先生，在担任主席职务两年后发表了告别演说"}},{"pos":"N-COUNT 可数名词","cn":"（优秀生在毕业典礼上作的）告别演说","en":"A valedictory is a speech that is given by the student with the highest marks in their class at their graduation ceremony.","ex":{"en":"He listened to Howard give the valedictory address at high school graduation.","cn":"他听了霍华德在中学毕业典礼上作的告别演讲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a speech or statement in which you say goodbye when you are leaving a school, job etc, especially on a formal occasion 〔","cn":"尤指在正式场合上的〕告别辞"}]},"vocab":{"pos":"n adj","senses":[{"en":"A valedictory is a speech expressing farewell, as at a school graduation. The adjective valedictory relates to saying good-bye, but almost always refers to a speech or address."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41valedictory.mp3","us":"media/ldoce/hwd/ame/e/valedictory.mp3"},"examples":[{"en":"a valedictory speech","cn":"告别演说"}],"oxford":{"phon":"ˌvælɪˈdɪktəri","pos":"adjective","senses":[{"en":"connected with saying goodbye, especially at a formal occasion","cn":"（尤在正式场合）告别的，告辞的","ex":{"en":"a valedictory speech","cn":"告别演说"}}]}},"valuer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"评估师;鉴定人;估价员","en":"A valuer is someone whose job is to estimate the cost or value of something, for example a house, or objects that are going to be sold in an auction."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to decide how much money something is worth","cn":"估价者"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41valuer.mp3","us":"media/ldoce/hwd/ame/a/ld41valuer.mp3"},"oxford":{"phon":"ˈvæljuːə(r)","pos":"noun","senses":[{"en":"a person whose job is to examine a building, an object, etc. and say how much it is worth","cn":"（房地产、物品等的）估价人，估值人"}]}},"validate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"证实;确证;确认","en":"To validate something such as a claim or statement means to prove or confirm that it is true or correct.","ex":{"en":"This discovery seems to validate the claims of popular astrology.","cn":"这个发现似乎能印证流行占星术的一些说法。"}},{"pos":"VERB 动词","cn":"证明…有价值;认可","en":"To validate a person, state, or system means to prove or confirm that they are valuable or worthwhile.","ex":{"en":"She is looking for an image that validates her","cn":"她在寻求一种能够证明自己价值的形象。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a piece of new information confirms an idea or belief that people already have, it shows that it is definitely true","cn":""},{"en":"to show that something is definitely true by providing facts","cn":""},{"en":"to provide additional information to help prove that a statement, belief, or explanation is correct","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To validate is to prove that something is based on truth or fact, or is acceptable. It can also mean to make something, like a contract, legal."}]},"media":{"uk":"media/ldoce/hwd/bre/e/validate0205.mp3","us":"media/ldoce/hwd/ame/3/validate.mp3"},"examples":[{"en":"Check that their courses have been validated by a reputable organization.","cn":"要确保他们的课程获得有声望机构的承认。"},{"en":"to validate a contract","cn":"使合同生效"}],"oxford":{"phon":"ˈvælɪdeɪt","pos":"verb","senses":[{"en":"to prove that something is true","cn":"证实；确认；确证","ex":{"en":"to validate a theory","cn":"证实理论"}},{"en":"to make something legally recognized","cn":"使生效；使有法律效力","ex":{"en":"to validate a contract","cn":"使合同生效"}},{"en":"to state officially that something is useful and of an acceptable standard","cn":"批准；确认…有效；认可","ex":{"en":"Check that their courses have been validated by a reputable organization.","cn":"要确保他们的课程获得有声望机构的承认。"}},{"en":"to recognize the value of a person or their feelings or opinions; to make somebody feel valued","cn":"承认（某人）的价值；认同（某人的感受或观点）；使感到受重视","ex":{"en":"Be sure to validate your child's feelings—don't minimize them.","cn":"一定要重视孩子的感受，千万不要不当回事。"}}]}},"vaseline":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"凡士林;矿脂","en":"Vaseline is a soft clear jelly made from petroleum, which is used to protect the skin and for other purposes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft clear substance used on the skin for various medical and other purposes","cn":"凡士林"}]},"media":{"uk":"media/ldoce/hwd/bre/8/vaseline0205.mp3","us":"media/ldoce/hwd/ame/1/vaseline.mp3"},"oxford":{"phon":"ˈvæsəliːn","pos":"noun","senses":[{"en":"a thick, soft, clear substance that is used on skin to protect it or to help a wound to get better, or as a lubricant to stop surfaces from sticking together","cn":"凡士林"}]}},"vanity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"虚荣(心);自负","en":"If you refer to someone's vanity, you are critical of them because they take great pride in their appearance or abilities.","ex":{"en":"Men who use steroids are motivated by sheer vanity","cn":"使用类固醇的男人纯粹是受虚荣心的驱使。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonable pride in your own abilities or qualities, which makes you behave rudely, as if other people were of no importance or interest","cn":""},{"en":"too much pride in your own abilities, appearance, or qualities, especially following a success which has made you behave as if you are very important","cn":""},{"en":"great pride in yourself so that you are always thinking about yourself, especially about your appearance","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vanity is the quality of being vain , or having a ridiculous amount of pride. If you have excessive vanity in your appearance, you probably spend long hours sitting at your vanity table doing your makeup or plucking your nose hairs."}]},"collocations":{"phrases":["ADJ. great | female, human, male, personal","VERB + VANITY appeal to, flatter My suggestion appealed to her vanity."]},"media":{"uk":"media/ldoce/hwd/bre/1/vanity0205.mp3","us":"media/ldoce/hwd/ame/1/vanity.mp3"},"examples":[{"en":"Politics is too often concerned only with the personal vanities of politicians.","cn":"政治常常仅与政界人士的个人虚荣有关。"},{"en":"the vanity of human ambition in the face of death","cn":"个人抱负在死亡面前的微不足道"}],"oxford":{"phon":"ˈvænəti","pos":"noun","senses":[{"en":"the fact of being too proud of your own appearance, abilities or achievements","cn":"自负；自大；虚荣；虚荣心","g":"[uncountable]","lab":"disapproving","ex":{"en":"She had no personal vanity (= about her appearance).","cn":"她对自己的相貌毫不自负。"}},{"en":"the fact of being unimportant, especially compared with other things that are important","cn":"（尤指与其他重大事物相比）渺小，无所谓，不重要","g":"[uncountable]","lab":"literary","ex":{"en":"the vanity of human ambition in the face of death","cn":"个人抱负在死亡面前的微不足道"}},{"en":"behaviour or attitudes that show people’s vanity","cn":"自负的行为；虚荣的态度；过分的骄傲","g":"[plural]","ex":{"en":"Politics is too often concerned only with the personal vanities of politicians.","cn":"政治常常仅与政界人士的个人虚荣有关。"}},{"en":"a piece of bedroom furniture like a table with drawers (= parts like boxes in it with handles on the front for pulling them open) and a mirror on top","cn":"梳妆台","g":"[countable]","lab":"North American English"}]}},"vanish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"消失;失踪;突然不见","en":"If someone or something vanishes, they disappear suddenly or in a way that cannot be explained.","ex":{"en":"He just vanished and was never seen again","cn":"他就这么消失了，再也没人见到过他。"}},{"pos":"VERB 动词","cn":"(物种）灭绝;（传统）消亡","en":"If something such as a species of animal or a tradition vanishes, it stops existing.","ex":{"en":"Near the end of Devonian times, thirty percent of all animal life vanished","cn":"在泥盆纪末期，30％的动物物种都灭绝了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something disappears, you cannot see it any longer, or it does not exist any longer","cn":""},{"en":"to completely disappear, especially suddenly","cn":""},{"en":"to stop existing – used about something bad such as a pain or a problem","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"A car driving into the distance, a member of a near-extinct species, or that last piece of pecan pie in the refrigerator — any of these things is likely to vanish soon, meaning \"to disappear.\""}]},"collocations":{"phrases":["ADV. just, simply I turned round and she had simply vanished. | abruptly, instantly, promptly, suddenly | quickly, rapidly Her feelings of s","VERB + VANISH seem to | make sb/sth","PREP. from All thoughts of romance vanished from his mind. | into She vanished into the mist.","PHRASES vanish from the face of the earth, vanish from sight, vanish into thin air At a stroke she could make things vanish into thin air. |","ADV. altogether, completely, entirely, totally Many of these old cinemas have now vanished altogether. | all but, almost, virtually country ","PREP. from This plant is vanishing from the British countryside."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdevanish.mp3","us":"media/ldoce/hwd/ame/9/vanish.mp3"},"examples":[{"en":"All hopes of a peaceful settlement had now vanished.","cn":"和平解决的全部希望现已化为泡影。"},{"en":"The magician vanished in a puff of smoke.","cn":"魔术师在一股烟雾中突然不见了。"}],"oxford":{"phon":"ˈvænɪʃ","pos":"verb","senses":[{"en":"to disappear suddenly and/or in a way that you cannot explain","cn":"（莫名其妙地）突然消失","g":"[intransitive]","ex":{"en":"He turned around and vanished into the house.","cn":"他转身消失在屋子里。"}},{"en":"to stop existing","cn":"不复存在；消亡；绝迹","g":"[intransitive]","ex":{"en":"the vanishing woodlands of Europe","cn":"不断消失的欧洲林地"}}]}},"vandalism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指对公共财产的）故意破坏，捣毁","en":"Vandalism is the deliberate damaging of things, especially public property.","ex":{"en":"...acts of vandalism.","cn":"故意破坏公共财产的行为"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of deliberately setting fire to a building","cn":""},{"en":"the crime of deliberately damaging things, especially public property","cn":"破坏财物（罪）〔尤指破坏公共财物〕"},{"en":"the crime of deliberately damaging things, especially public property","cn":"破坏财物（罪）〔尤指破坏公共财物〕"}]},"vocab":{"pos":"n","senses":[{"en":"Vandalism is the destruction of someone else's property. Some people think of graffiti as public art, while others dismiss it as nothing but vandalism ."}]},"collocations":{"phrases":["ADJ. mindless, wanton | criminal | environmental","VERB + VANDALISM discourage, prevent","PHRASES an act of vandalism"]},"media":{"uk":"media/ldoce/hwd/bre/c/vandalism0205.mp3","us":"media/ldoce/hwd/ame/5/vandalism.mp3"},"examples":[{"en":"an act of vandalism","cn":"恣意破坏公共财物的行为"}],"oxford":{"phon":"ˈvændəlɪzəm","pos":"noun","senses":[{"en":"the crime of destroying or damaging something, especially public property, deliberately and for no good reason","cn":"故意破坏公共财物罪；恣意毁坏他人财产罪","lab":"British English","ex":{"en":"an act of vandalism","cn":"恣意破坏公共财物的行为"}}]}},"vacationer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（在某地）度假的人，度假者","en":"Vacationers are people who are on vacation in a particular place."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has gone somewhere for a holiday","cn":"度假者"}]},"media":{"uk":"media/ldoce/hwd/bre/c/vacationer0205.mp3","us":"media/ldoce/hwd/ame/2/vacationer.mp3"},"oxford":{"phon":"veɪˈkeɪʃənə(r)","pos":"noun","senses":[{"en":"a person who is visiting a place on holiday","cn":"度假者","ex":{"en":"Most vacationers stay in the downtown area.","cn":"大多数度假者住在市中心。"}}]}},"vandalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"故意破坏;肆意捣毁","en":"If something such as a building or part of a building is vandalized by someone, it is damaged on purpose.","ex":{"en":"The walls had been horribly vandalized with spray paint","cn":"墙壁被用喷漆喷得一塌糊涂。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cause physical harm to something or someone, or have a bad effect on them","cn":""},{"en":"to have a bad effect on something","cn":""},{"en":"to have a bad effect on something and make it less successful, enjoyable, useful etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/vandalize0205.mp3","us":"media/ldoce/hwd/ame/7/laadvandalize.mp3"},"examples":[{"en":"The cemetery was vandalized during the night.","cn":"公墓在夜间遭到了破坏。"}],"oxford":{"phon":"ˈvændəlaɪz","pos":"verb","senses":[{"en":"to damage something, especially public property, deliberately and for no good reason","cn":"故意破坏，肆意破坏（尤指公共财物）","ex":{"en":"The pay phone had been vandalized and wasn’t working.","cn":"这部公用电话已遭破坏，不能使用了。"}}]}},"vampire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（传说和恐怖故事中在夜间离开坟墓吸食活人血的）吸血鬼","en":"A vampire is a creature in legends and horror stories. Vampires are said to come out of graves at night and suck the blood of living people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"in stories, a dead person that sucks people’s blood by biting their necks","cn":"吸血鬼"}]},"vocab":{"pos":"n","senses":[{"en":"Although traditionally used to refer to the bloodsucking undead, you can use the noun vampire to describe someone who heartlessly preys on others — a blackmailer, or anyone else who just sucks the life out of you."}]},"media":{"uk":"media/ldoce/hwd/bre/8/vampire0205.mp3","us":"media/ldoce/hwd/ame/4/vampire.mp3"},"oxford":{"phon":"ˈvæmpaɪə(r)","pos":"noun","senses":[{"en":"a dead person who leaves their grave (= where they are buried) at night to bite living people and drink their blood","cn":"吸血鬼（夜间走出坟墓吸吮活人血液）"}]}},"valance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（装饰床沿的）挂布，挂帘，短帷幔","en":"A valance is a piece of cloth that hangs down over the sides of a bed in order to make it look nice."},{"pos":"N-COUNT 可数名词","cn":"（窗户顶部的）木框，短帷幔","en":"A valance is a long narrow piece of wood or fabric which is fitted at the top of a window for decoration and to hide the curtain rail."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a narrow piece of cloth that hangs from the edge of a shelf or from the frame of a bed to the floor 〔","cn":"挂在架子边缘﹑床沿等的〕挂帘﹐短帷幔﹐挂布"},{"en":"a narrow piece of cloth above a window, covering the rail the curtains hang on 〔","cn":"窗帘上端的〕布帷幔"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41valance.mp3","us":"media/ldoce/hwd/ame/0/valance.mp3"},"oxford":{"phon":"ˈvæləns","pos":"noun","senses":[{"en":"a narrow piece of cloth like a short curtain that hangs around the frame of a bed, under a shelf, etc.","cn":"（床架等四周的）短帷幔，布帘"},{"en":"a narrow piece of wood or cloth above a window that hides the curtain rail","cn":"窗帘盒；窗帘短帷幔","lab":"especially North American English"}]}},"vagrant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"流浪汉;漂泊者;乞丐","en":"A vagrant is someone who moves a lot from place to place because they have no permanent home or job, and have to ask for or steal things in order to live.","ex":{"en":"He lived on the street as a vagrant.","cn":"他以在大街上乞讨为生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has no home or regular work","cn":""},{"en":"a person, usually a man, who has no home or regular job and asks people for money on the streets","cn":""},{"en":"a woman with no home or job who carries all her possessions around with her in a bag","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A vagrant is someone who is homeless and poor and may wander from place to place. In fiction a vagrant often is a criminal, but a real-life vagrant might just be a person who has lost a job and family and lives off the streets with help from charity."}]},"media":{"uk":"media/ldoce/hwd/bre/1/vagrant0205.mp3","us":"media/ldoce/hwd/ame/a/vagrant.mp3"},"oxford":{"phon":"ˈveɪɡrənt","pos":"noun","senses":[{"en":"a person who has no home or job, especially one who begs (= asks for money) from people","cn":"无业游民；流浪者；（尤指）乞丐","ex":{"en":"The accused was a vagrant who travelled around, sleeping in parks and bus shelters.","cn":"被告人是一个四处游走的睡在公园和候车亭的流浪汉。"}},{"en":"having no home or job","cn":"流浪的","ex":{"en":"a vagrant beggar","cn":"流浪乞丐"},"pos":"adjective"}]}},"vascular":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"血管的;(动物)脉管的;(植物)维管的","en":"Vascular is used to describe the channels and veins through which fluids pass in the bodies of animals and plants.","ex":{"en":"...the oldest known vascular plants.","cn":"已知的最古老的维管植物"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the tubes through which liquids flow in the bodies of animals or in plants 〔","cn":"动物〕脉管的﹔〔植物〕维管的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective vascular when you're talking about blood vessels. One side effect of long-term smoking is vascular disease."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vascular0205.mp3","us":"media/ldoce/hwd/ame/5/vascular.mp3"},"examples":[{"en":"vascular disease","cn":"脉管疾病"}],"oxford":{"phon":"ˈvæskjələ(r)","pos":"adjective","senses":[{"en":"of or containing veins (= the tubes that carry liquids around the bodies of animals and plants)","cn":"血管的；脉管的；维管的","ex":{"en":"the vascular system","cn":"血管系统;淋巴管系统"}}]}},"vacuum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"空位;空缺;空白","en":"If someone or something creates a vacuum, they leave a place or position which then needs to be filled by another person or thing.","ex":{"en":"The collapse of the army left a vacuum in the area","cn":"这支军队的溃败使这个地区出现了军事真空。"}},{"pos":"PHRASE 短语","cn":"在封闭状态中;与外界隔绝","en":"If something is done in a vacuum, it is not affected by any outside influences or information.","ex":{"en":"Moral values cannot be taught in a vacuum","cn":"道德价值观的教育不能脱离实际。"}},{"pos":"VERB 动词","cn":"用真空吸尘器打扫","en":"If you vacuum something, you clean it using a vacuum cleaner.","ex":{"en":"I vacuumed the carpets today","cn":"今天我用吸尘器清洁了地毯。"}},{"pos":"N-COUNT 可数名词","cn":"真空","en":"A vacuum is a space that contains no air or other gas.","ex":{"en":"Wind is a current of air caused by a vacuum caused by hot air rising","cn":"风是由于热空气上升产生真空导致的一种气流运动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a space that is completely empty of all gas, especially one from which all the air has been taken away","cn":"真空"},{"en":"a vacuum cleaner","cn":"真空吸尘器"},{"en":"a situation in which someone or something is missing or lacking","cn":"空白﹔空虚"}]},"vocab":{"pos":"n v","senses":[{"en":"A vacuum is essentially a great lack of something — a place where virtually all matter, even air, has been removed. It can describe something that's literally empty — or something that just seems that way, like a political vacuum."}]},"collocations":{"phrases":["ADJ. perfect | moral, political, spiritual The writer criticized the moral vacuum in society. | power Her resignation left a power vacuum in","VERB + VACUUM create, leave, produce The machine then creates a vacuum. | fill Other gases rush in to fill the vacuum."]},"media":{"uk":"media/ldoce/hwd/bre/3/vacuum_las2_br.mp3","us":"media/ldoce/hwd/ame/d/vacuum1.mp3"},"examples":[{"en":"His resignation has created a vacuum which cannot easily be filled.","cn":"他的引退造成了难以填补的空白。"},{"en":"to give a room a quick vacuum","cn":"用吸尘器把房间迅速清扫一下"}],"oxford":{"phon":"ˈvækjuːm","pos":"noun","senses":[{"en":"a space that is completely empty of all substances, including all air or other gas","cn":"真空","ex":{"en":"a vacuum pump (= one that creates a vacuum)","cn":"真空泵"}},{"en":"a situation in which somebody/something is missing","cn":"真空状态；空白；空虚","g":"[usually singular]","ex":{"en":"His resignation has created a vacuum which cannot easily be filled.","cn":"他的引退造成了难以填补的空白。"}},{"en":"the act of cleaning something with a vacuum cleaner","cn":"（用真空吸尘器所做的）清洁，清扫","g":"[usually singular]","ex":{"en":"to give a room a quick vacuum","cn":"用吸尘器把房间迅速清扫一下"}},{"en":"to clean something using a vacuum cleaner","cn":"用真空吸尘器清扫","ex":{"en":"Have you vacuumed the stairs?","cn":"你用吸尘器清扫楼梯了吗？"},"pos":"verb"}]}},"valour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指战争中的)英勇表现，勇气，勇猛","en":"Valour is great bravery, especially in battle. discretion is the better part of valour→see: ;","ex":{"en":"He was himself decorated for valour in the war.","cn":"他自己因在战争中的英勇表现而获得了勋章。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"great courage, especially in war 〔","cn":"尤指在战争中的〕勇猛﹐勇武"}]},"collocations":{"phrases":["ADJ. great a soldier famed for his great valour","VERB + VALOUR demonstrate, display, show He showed valour and skill on the battlefield.","PREP. an act/a deed of valour"]},"media":{"uk":"media/ldoce/hwd/bre/0/valour0205.mp3","us":"media/ldoce/hwd/ame/b/valor.mp3"},"examples":[{"en":"medals awarded for valor","cn":"表彰英勇的勋章"},{"en":"deeds of valour","cn":"英勇事迹"}],"oxford":{"phon":"ˈvælə(r)","pos":"noun","senses":[{"en":"great courage, especially in war","cn":"（尤指战争中的）英勇，勇气","ex":{"en":"He showed valour and skill on the battlefield.","cn":"他在战场上表现得骁勇善战。"}}]}},"variability":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feelings or conditions that are changeable change frequently so that it is difficult to know what they will be like in a short time","cn":""},{"en":"behaviour, processes, or services that are erratic change suddenly in an unexpected and surprising way, when it would be better if they remained the same","cn":""},{"en":"a volatile situation or character is likely to change suddenly and unexpectedly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The weather in San Francisco is known for its variability . One minute it's summer and the next, winter. Variability means the tendency to shift or change — of being \"variable.\""}]},"collocations":{"phrases":["ADJ. considerable, extreme, great, high, wide There is considerable variability in all the test scores. | low, slight","QUANT. degree","PREP. ~ among/between variability among different health authorities | ~ in variability in crop yields"]},"media":{"uk":"media/ldoce/hwd/bre/6/variable_adj0205.mp3","us":"media/ldoce/hwd/ame/2/l3variable.mp3"},"examples":[{"en":"a degree of variability in the exchange rate","cn":"汇率的变化幅度"},{"en":"climatic variability","cn":"气候的多变性"}],"oxford":{"phon":"ˌveəriəˈbɪləti","pos":"noun","senses":[{"en":"the fact of something being likely to vary","cn":"可变性；易变性；反复不定","ex":{"en":"The changes were attributed to natural climatic variability.","cn":"这些变更是自然气候多变造成的。"}}]}},"vault":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"金库;保险库","en":"A vault is a secure room where money and other valuable things can be kept safely.","ex":{"en":"Most of the money was in storage in bank vaults","cn":"大部分钱都存放在银行的保险库里。"}},{"pos":"N-COUNT 可数名词","cn":"（通常指安葬同一家族死者的）教堂地下室，墓穴,墓室","en":"A vault is a room underneath a church or in a cemetery where people are buried, usually the members of a single family.","ex":{"en":"He ordered that Matilda's body should be buried in the family vault.","cn":"他指示马蒂尔达的遗体必须葬在家族墓穴里。"}},{"pos":"N-COUNT 可数名词","cn":"拱顶;穹窿","en":"A vault is an arched roof or ceiling.","ex":{"en":"...the vault of a great cathedral.","cn":"一座大教堂的拱顶"}},{"pos":"VERB 动词","cn":"（尤指用手支撑）跳跃,跳过","en":"If you vault something or vault over it, you jump quickly onto or over it, especially by putting a hand on top of it to help you balance while you jump.","ex":{"en":"He could easily vault the wall","cn":"他可以轻松地翻过墙去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room with thick walls and a strong door where money, jewels etc are kept to prevent them from being stolen or damaged 〔","cn":"贵重财物的〕保管库﹐保险库﹔金库"},{"en":"a room where people from the same family are buried, often under the floor of a church 〔","cn":"常指教堂地下某一家族的〕墓穴﹐墓室"},{"en":"a jump over something","cn":"跳跃﹐腾跃"}]},"vocab":{"pos":"n v","senses":[{"en":"Vault is a verb that means \"to jump over something.\" If you were hurrying out to the pasture to visit your favorite cow, you might vault over the gate in your excitement."}]},"collocations":{"phrases":["ADJ. secure | bank, museum | treasure","VERB + VAULT keep/store sth in","PREP. in a/the ~ The jewels were kept in a bank vault. 2 room under a church where dead people are buried","ADJ. burial, family, royal","VERB + VAULT bury sb in She is to be buried in the family vault."]},"media":{"uk":"media/ldoce/hwd/bre/1/vault_v0205.mp3","us":"media/ldoce/hwd/ame/2/vault1.mp3"},"examples":[{"en":"She vaulted over the gate and ran up the path.","cn":"她用手一撑跃过栅栏门沿着小路跑去。"},{"en":"to vault a fence","cn":"跃过篱笆墙"}],"oxford":{"phon":"vɔːlt","pos":"noun","senses":[{"en":"a room with thick walls and a strong door, especially in a bank, used for keeping valuable things safe","cn":"（尤指银行的）金库，保险库","ex":{"en":"Most of her jewellery is stored in bank vaults.","cn":"她的大部分珠宝都存放在银行金库中。"}},{"en":"a room under a church or in a cemetery, used for burying people","cn":"（教堂的）地下墓室；（坟地的）墓穴","ex":{"en":"She is to be buried in the family vault.","cn":"她将安葬在家族墓穴里。"}},{"en":"a roof or ceiling in the form of an arch or a series of arches","cn":"穹顶；拱顶；穹隆"},{"en":"a jump made by vaulting","cn":"撑物跳高；撑竿跳"},{"en":"to jump over an object in a single movement, using your hands or a pole to push you","cn":"（用手支撑或撑竿）跳跃，腾跃","ex":{"en":"She vaulted over the gate and ran up the path.","cn":"她用手一撑跃过栅栏门沿着小路跑去。"},"pos":"verb"}]}},"vagrancy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"流浪;漂泊","en":"Vagrancy is a way of life in which someone moves a lot from place to place because they have no permanent home or job, and have to ask for or steal things in order to live.","ex":{"en":"Vagrancy and begging has become commonplace in London.","cn":"流浪和乞讨在伦敦已变得很常见。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the criminal offence of living on the street and begging ( beg ) from people","cn":"流浪罪"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41vagrancy.mp3","us":"media/ldoce/hwd/ame/b/vagrancy.mp3"},"oxford":{"phon":"ˈveɪɡrənsi","pos":"noun","senses":[{"en":"the crime of living on the streets and begging (= asking for money) from people","cn":"流浪罪；流浪行乞","ex":{"en":"He was convicted of drunkenness and vagrancy.","cn":"他被判犯有酗酒和流浪罪。"}}]}},"valentine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"情人节贺卡","en":"A valentine or a valentine card is a greetings card that you send to someone who you are in love with or are attracted to, usually without signing your name, on St Valentine's Day, the 14th of February."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone you love or think is attractive, that you send a card to on St Valentine’s Day 〔","cn":"在圣瓦伦丁节(2月14日)向其赠送贺卡的〕情人"},{"en":"a card you send to someone on St Valentine’s Day","cn":"圣瓦伦丁节贺卡﹐情人卡"}]},"vocab":{"pos":"n","senses":[{"en":"A valentine is a sweetheart: specifically, someone who receives a greeting or attention on Valentine's Day."}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdevalentine.mp3","us":"media/ldoce/hwd/ame/3/amelasdevalentine.mp3"},"examples":[{"en":"Be my valentine.","cn":"做我的情人吧。"}],"oxford":{"phon":"ˈvæləntaɪn","pos":"noun","senses":[{"en":"a card that you send to somebody that you love on St Valentine’s Day (14 February), often without putting your name on it","cn":"（在 2 月 14 日常匿名寄送的）圣瓦伦丁节情人卡"},{"en":"a person that you send a valentine to","cn":"（收到情人节卡片的）情人"}]}},"vamp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（利用色相勾引男人的）荡妇，妖妇，女骗子","en":"If you describe a woman as a vamp, you mean that she uses her sexual attractiveness to get what she wants from men."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who uses her sexual attractiveness to make men do what she wants 〔","cn":"利用色相勾引并利用男子的〕妖妇﹐荡妇"}]},"vocab":{"pos":"1 n v 2 n v 3 n 4 v","senses":[{"en":"A vamp is an attractive, dangerously flirtatious woman. A vamp in an old movie might wear tight clothes and bright red lipstick."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vamp.mp3","us":"media/ldoce/hwd/ame/f/vamp.mp3"},"oxford":{"phon":"væmp","pos":"noun","senses":[{"en":"a woman who is thought to be sexually attractive and trying to control men","cn":"妖妇（利用色相控制男性）"}]}},"vacuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"思想贫乏的;空洞的;无知的","en":"If you describe a person or their comments as vacuous, you are critical of them because they lack intelligent thought or ideas.","ex":{"en":"Male models are not always so vacuous as they are made out to be.","cn":"男模特儿并不总像人们说的那样愚蠢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing no intelligence or having no useful purpose","cn":"无知的﹔空洞的﹔没有意义的"}]},"vocab":{"pos":"adj","senses":[{"en":"Reserved for the harmlessly stupid and truly meaningless, vacuous is a smart-sounding way to describe something dumb. Celebrity gossip and reality TV is usually pretty vacuous , even if it's fun."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vacuous.mp3","us":"media/ldoce/hwd/ame/9/vacuous.mp3"},"examples":[{"en":"a vacuous expression","cn":"茫然的表情"},{"en":"a vacuous romantic novel","cn":"空洞的爱情小说"}],"oxford":{"phon":"ˈvækjuəs","pos":"adjective","senses":[{"en":"showing no sign of intelligence or sensitive feelings","cn":"空洞的；空洞无物的","ex":{"en":"a vacuous expression","cn":"茫然的表情"}}]}},"vanquish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（彻底）征服，击败，战胜","en":"To vanquish someone means to defeat them completely in a battle or a competition.","ex":{"en":"A happy ending is only possible because the hero has first vanquished the dragons","cn":"只有主人公先把那些恶龙制服，才有可能实现大团圆结局。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to defeat someone or something completely","cn":"彻底征服﹐彻底击败"}]},"vocab":{"pos":"v","senses":[{"en":"To vanquish is to be the complete and total winner, to overpower and overcome, whether in a contest, a race, or a war. It generally suggests a total trouncing, to the point of humiliation — or worse — for the loser."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vanquish0205.mp3","us":"media/ldoce/hwd/ame/0/vanquish.mp3"},"oxford":{"phon":"ˈvæŋkwɪʃ","pos":"verb","senses":[{"en":"to defeat somebody completely in a competition, war, etc.","cn":"完全征服；彻底击败；战胜","ex":{"en":"Government forces vanquished the rebels.","cn":"政府军彻底击败了叛乱分子。"}}]}},"vacillate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"犹豫不定;踌躇;拿不定主意","en":"If you vacillate between two alternatives or choices, you keep changing your mind.","ex":{"en":"She vacillates between men twice her age and men younger than she","cn":"她犹豫不决，不知道是该选择年龄比她大一倍的男人还是比她小的男人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to keep changing your mind about what you believe or what you are going to do, especially when you have two choices and you cannot decide which one is best","cn":""},{"en":"someone who is fickle is always changing their mind about the people or things that they like so you cannot depend on them","cn":""},{"en":"if someone blows hot and cold about something, they keep changing their attitude so that sometimes they are eager to do it and at other times they are unwilling","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Vacillate means to waver back and forth, unable to decide. You might vacillate between ordering waffles and pancakes at your favorite diner — it’s hard to pick just one when both are so tasty!"}]},"media":{"uk":"media/ldoce/hwd/bre/2/vacillate0205.mp3","us":"media/ldoce/hwd/ame/3/vacillate.mp3"},"examples":[{"en":"Her parents vacillated between different approaches to discipline.","cn":"她的父母在不同的管教方式之间摇摆不定。"}],"oxford":{"phon":"ˈvæsəleɪt","pos":"verb","senses":[{"en":"to keep changing your opinion or thoughts about something, especially in a way that annoys other people","cn":"观点（或立场等）摇摆；动摇","ex":{"en":"The country’s leaders are still vacillating between confrontation and compromise.","cn":"该国领导人仍在对抗与妥协之间摇摆不定。"}}]}},"vassal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（封建社会的）封臣","en":"In feudal society, a vassal was a man who gave military service to a lord, in return for which he was protected by the lord and received land to live on."},{"pos":"N-COUNT 可数名词","cn":"附属国","en":"If you say that one country is a vassal of another, you mean that it is controlled by it.","ex":{"en":"Opponents of the treaty argue that monetary union will turn France into a vassal of Germany.","cn":"协定的反对者认为货币联盟会使法国沦为德国的附庸国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man in the Middle Ages who was given land to live on by a lord in return for promising to work or fight for him 〔","cn":"中世纪领主下面的〕封臣﹐家臣〔对国君或领主效忠﹐作为回报获封土地〕"},{"en":"a country that is controlled by another country","cn":"附属国﹐属地"}]},"vocab":{"pos":"n","senses":[{"en":"If this were Medieval Europe, you would probably be a vassal — like most everyone else. Vassals were people who worked the vast plots of land that were held by lords, who though much fewer in number, held all the wealth and power."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41vassal.mp3","us":"media/ldoce/hwd/ame/1/vassal.mp3"},"examples":[{"en":"a vassal state","cn":"附庸国"}],"oxford":{"phon":"ˈvæsl","pos":"noun","senses":[{"en":"a man in the Middle Ages who promised to fight for and show support for a king or other powerful owner of land, in return for being given land to live on","cn":"封臣，家臣（中世纪为国王或其他权贵效忠的受封者）"},{"en":"a country that depends on and is controlled by another country","cn":"附庸国；属国","ex":{"en":"a vassal state","cn":"附庸国"}}]}},"vacant":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未使用的;未被占用的;空的","en":"If something is vacant, it is not being used by anyone.","ex":{"en":"Half way down the coach was a vacant seat","cn":"车厢中部有一个空座。"}},{"pos":"ADJ 形容词","cn":"(工作或职位）空缺的","en":"If a job or position is vacant, no one is doing it or in it at present, and people can apply for it.","ex":{"en":"A number of senior people were regarded as likely to occupy the now vacant post","cn":"几位资深人士被认为有望填补现在空缺的职位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（神情）茫然的;失神的","en":"A vacant look or expression is one that suggests that someone does not understand something or that they are not thinking about anything in particular.","ex":{"en":"She had a kind of vacant look on her face.","cn":"她脸上有种茫然的神情。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used about a place that has no one in it or no one using it","cn":""},{"en":"used about a seat, space, or room that is available to use because no one else is using it","cn":""},{"en":"used about a room or building that is available for people to pay to use","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You can use the adjective vacant to describe something that is empty — an apartment with no tenant or furniture, a job with no worker, or a person with no brainpower."}]},"collocations":{"phrases":["VERBS be | become, fall (only used of jobs) A seat became vacant and he sat down in it. A job fell vacant in the accounting department. | re"]},"media":{"uk":"media/ldoce/hwd/bre/e/vacant0205.mp3","us":"media/ldoce/hwd/ame/6/vacant.mp3"},"examples":[{"en":"When the post finally fell (= became) vacant, they offered it to Fiona.","cn":"这个职位最终空出来之后，他们给了菲奥纳。"},{"en":"The seat next to him was vacant.","cn":"他旁边的座位空着。"}],"oxford":{"phon":"ˈveɪkənt","pos":"adjective","senses":[{"en":"empty; not being used","cn":"空着的；未被占用的","lab":"especially North American English","ex":{"en":"There are very few vacant properties available in the area.","cn":"这个地区很少有闲置的房产。"}},{"en":"if a job in a company is vacant, nobody is doing it and it is available for somebody to take","cn":"（职位）空缺的","lab":"formal","ex":{"en":"When the post finally fell (= became) vacant, they offered it to Fiona.","cn":"这个职位最终空出来之后，他们把它给了菲奥纳。"}},{"en":"showing no sign that the person is thinking of anything","cn":"无神的；呆滞的；茫然的；若有所失的","ex":{"en":"a vacant look","cn":"呆滞的目光"}}]}},"vaccination":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to protect a person or animal from a disease by giving them a vaccine","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vaccination is the act of getting a shot (a vaccine) to protect you against a certain disease. If you want to protect yourself from catching the mumps, you will need to undergo a vaccination ."}]},"collocations":{"phrases":["ADJ. flu, measles, rubella, smallpox, etc.","VERB + VACCINATION have | give sb","VACCINATION + NOUN campaign, programme","PREP. ~ against a vaccination against tetanus"]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vaccinate.mp3","us":"media/ldoce/hwd/ame/b/vaccinate.mp3"},"examples":[{"en":"Make sure your vaccinations are up to date.","cn":"一定要接种最新的疫苗。"},{"en":"vaccination against typhoid","cn":"伤寒疫苗的接种"}],"oxford":{"phon":"ˌvæksɪˈneɪʃn","pos":"noun","senses":[{"en":"the act of giving a person or an animal a vaccine in order to protect them against a disease; the fact of having received a vaccine","cn":"接种疫苗","ex":{"en":"Make sure your vaccinations are up to date.","cn":"一定要接种最新的疫苗。"}}]}},"vandal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指破坏公共财产的）破坏分子，捣毁者","en":"A vandal is someone who deliberately damages things, especially public property.","ex":{"en":"All information systems that have been fitted at Ashford station have now been destroyed by vandals.","cn":"安装在阿什福德车站的所有信息查询装置如今都被破坏分子毁坏了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who steals things","cn":""},{"en":"someone who steals money or valuable things from a bank, shop etc – used especially when someone sees the person who is stealing","cn":""},{"en":"someone who goes into people’s homes in order to steal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A vandal is someone who harms or destroys other people's property. Someone who paints graffiti on your door is a vandal."}]},"collocations":{"phrases":["ADJ. car Car vandals caused more than &pound; 10,000 worth of damage to vehicles last Saturday.","VERB + VANDAL deter, discourage The windows are covered with grilles to deter vandals.","VANDAL + VERB damage sth, wreck sth"]},"media":{"uk":"media/ldoce/hwd/bre/f/vandal0205.mp3","us":"media/ldoce/hwd/ame/0/vandal.mp3"},"oxford":{"phon":"ˈvændl","pos":"noun","senses":[{"en":"a person who deliberately destroys or damages public property","cn":"故意破坏公物者","ex":{"en":"Vandals broke into the factory and set fire to a cabin.","cn":"破坏分子闯入工厂将小木屋付之一炬。"}}]}},"valet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（男子的）贴身男仆,男仆从","en":"A valet is a male servant who looks after his employer by doing things such as caring for his clothes and cooking for him."},{"pos":"VERB 动词","cn":"(受雇）洗（车）","en":"If someone valets a vehicle, they are paid to clean it thoroughly inside and out."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male servant who looks after a man’s clothes, serves his meals etc 〔","cn":"男子的〕贴身男仆﹐男仆从"},{"en":"someone who parks your car for you at a restaurant, hotel etc 〔","cn":"餐厅或酒店等场所〕为客人停车的人"},{"en":"someone who cleans the clothes of people staying in a hotel 〔","cn":"为酒店客人洗衣服的〕服务员"}]},"vocab":{"pos":"n v","senses":[{"en":"A valet is like a butler: a servant who attends to his employer's needs."}]},"media":{"uk":"media/ldoce/hwd/bre/d/valet_n0205.mp3","us":"media/ldoce/hwd/ame/b/valet.mp3"},"examples":[{"en":"a car valeting service","cn":"清洗汽车服务"},{"en":"valet service","cn":"代客泊车服务"}],"oxford":{"phon":"ˈvæleɪ","pos":"noun","senses":[{"en":"a man’s personal servant who takes care of his clothes, serves his meals, etc.","cn":"（照管男子衣食等的）贴身仆人，仆从","ex":{"en":"His valet brought him his letters.","cn":"他的贴身仆人给他送来了信件。"}},{"en":"a hotel employee whose job is to clean the clothes of hotel guests","cn":"（旅馆中）为顾客洗衣服的服务员"},{"en":"a person who parks your car for you at a hotel or restaurant","cn":"（旅馆或餐厅）为顾客停车的服务员","lab":"especially North American English"},{"en":"to clean a person’s car carefully and completely, especially on the inside","cn":"彻底清洗（尤指车内）","g":"[transitive]","lab":"British English","ex":{"en":"a car valeting service","cn":"清洗汽车服务"},"pos":"verb"},{"en":"to perform the duties of a valet","cn":"侍候；服侍","g":"[intransitive]","pos":"verb"}]}},"variously":{"collins":{"senses":[{"pos":"ADV 副词","cn":"不同地;以各种方式","en":"You can use variously to introduce a number of different ways in which something can be described.","ex":{"en":"...the crowds, which were variously estimated at two to several thousand","cn":"人数估计不一、从两千人到数千人不等的人群"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in many different ways","cn":"以各种不同的方式"},{"en":"variously described as/known as/called etc something the phenomena variously known as ‘mass culture’, ‘popular culture’, or the ‘public arts’","cn":"被冠以不同名称如“大众文化”﹑“通俗文化”或“大众艺术”的现象 His fortune has been variously estimated at between $1 and $2 billion. 对他的财富有各种猜测﹐从10亿美元"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdevariously.mp3","us":"media/ldoce/hwd/ame/5/variously.mp3"},"examples":[{"en":"The cost has been variously estimated at between £10 million and £20 million.","cn":"对成本的估计众说纷纭，从 1 000 万英镑到 2 000 万英镑不等。"},{"en":"He has been variously described as a hero, a genius and a bully.","cn":"他被描述为英雄、天才、恶霸，不一而足。"}],"oxford":{"phon":"ˈveəriəsli","pos":"adverb","senses":[{"en":"in several different ways, usually by several different people","cn":"以各种方式；不同地","ex":{"en":"He has been variously described as a hero, a genius and a bully.","cn":"他被描述为英雄、天才、恶霸，不一而足。"}}]}},"vaginal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"阴道的","en":"Vaginal means relating to or involving the vagina.","ex":{"en":"The creams have been used to reduce vaginal infections.","cn":"已使用这种乳膏来减少阴道感染。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the passage between a woman’s outer sexual organs and her uterus","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/vagina0205.mp3","us":"media/ldoce/hwd/ame/5/vagina.mp3"},"oxford":{"phon":"vəˈdʒaɪnl","pos":"adjective","senses":[{"en":"connected with the vagina","cn":"阴道的"}]}},"vase":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花瓶;（装饰用的）瓶","en":"A vase is a jar, usually made of glass or pottery, used for holding cut flowers or as an ornament.","ex":{"en":"...a vase of red roses.","cn":"一花瓶的红玫瑰"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container used to put flowers in or for decoration","cn":"花瓶﹐〔装饰用的〕瓶"}]},"collocations":{"phrases":["ADJ. flower | china, crystal, cut-glass, glass, porcelain, silver, stone","VASE + VERB be filled with sth, contain sth, hold sth | stand A silver vase stood on the mantelpiece.","PREP. in a/the ~ flowers arranged in a vase | ~ of a vase of fresh flowers"]},"media":{"img":["media/ldoce/img/vase.jpg"],"uk":"media/ldoce/hwd/bre/c/vase0205.mp3","us":"media/ldoce/hwd/ame/c/vase.mp3"},"examples":[{"en":"a vase of flowers","cn":"一瓶花"}],"oxford":{"phon":"vɑːz","pos":"noun","senses":[{"en":"a container made of glass, etc., used for holding cut flowers or as an attractive object","cn":"花瓶；装饰瓶","ex":{"en":"a vase of flowers","cn":"一瓶花"}}]}},"vacate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"腾出（空间）;辞去（职位）","en":"If you vacate a place or a job, you leave it or give it up, making it available for other people.","ex":{"en":"He vacated the flat and went to stay with an uncle","cn":"他搬出了公寓，住到了他的一个叔叔那里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to leave your home or the area where you live","cn":""},{"en":"to permanently leave your home, usually one you rent or share with someone else, taking all your possessions with you","cn":""},{"en":"if a young person leaves home , they leave their parents' house because they think they are old enough to live on their own","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If someone asks you to vacate the room, you'd better pack up your things and go. When you vacate something, you leave it behind, usually empty."}]},"media":{"uk":"media/ldoce/hwd/bre/d/vacate0205.mp3","us":"media/ldoce/hwd/ame/e/vacate.mp3"},"examples":[{"en":"Guests are requested to vacate their rooms by noon on the day of departure.","cn":"房客务请在离开之日的中午以前腾出房间。"},{"en":"Clay will vacate the position on June 19.","cn":"克莱将于6月19日离职。"}],"oxford":{"phon":"vəˈkeɪt","pos":"verb","senses":[{"en":"to leave a building, seat, etc., especially so that somebody else can use it","cn":"搬出，腾出，空出（建筑物、座位等）","ex":{"en":"Guests are requested to vacate their rooms by noon on the day of departure.","cn":"房客务请在离开之日的中午以前腾出房间。"}},{"en":"to leave a job, position of authority, etc. so that it is available for somebody else","cn":"辞（职）；让（位）","ex":{"en":"She has taken over the role vacated by her boss.","cn":"她接任了她老板腾出来的职位。"}}]}},"valium":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"安定(一种镇静药)","en":"Valium is a drug given to people to calm their nerves when they are very depressed or upset."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug that makes people feel calmer and less anxious Valium","cn":"牌安定〔一种镇静药〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/valium0205.mp3","us":"media/ldoce/hwd/ame/d/valium.mp3"},"oxford":{"phon":"ˈvæliəm","pos":"noun","senses":[{"en":"a drug used to reduce anxiety (= feelings of fear and worry)","cn":"安定（一种抗焦虑药物）"}]}},"vale":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谷;山谷","en":"A vale is a valley.","ex":{"en":"...a small vale, sheltering under mist-shrouded hills.","cn":"隐蔽在雾气笼罩的山丘下的小山谷"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a broad low valley","cn":"谷﹔山谷"},{"en":"an expression used to mean the difficulties of life","cn":"生活的磨难﹐烦恼的尘世"}]},"vocab":{"pos":"n","senses":[{"en":"A vale is a long depression in the land, usually between two hills and containing a river. A vale is a valley."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41vale.mp3","us":"media/ldoce/hwd/ame/c/vail.mp3"},"examples":[{"en":"the Vale of the White Horse","cn":"怀特霍斯谷"},{"en":"a wooded vale","cn":"树木茂密的山谷"}],"oxford":{"phon":"veɪl","pos":"noun","senses":[{"en":"a valley","cn":"谷；山谷","ex":{"en":"a wooded vale","cn":"树木茂密的山谷"}}]}},"valedictorian":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（中学或大学毕业典礼上）致告别词的优秀毕业生","en":"A valedictorian is the student who has the highest marks in their class when they graduate from high school, college, or university, and who gives a speech at their graduation ceremony."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the student who has received the best marks all the way through school, and who usually makes a speech at the graduation ceremony","cn":"致告别词的毕业生代表〔通常为成绩最优秀者〕"}]},"vocab":{"pos":"n","senses":[{"en":"The valedictorian is usually the student with the highest grades in a class. If the valedictorian of your class is someone you like and admire, you'll enjoy listening to her graduation speech."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41valedictorian.mp3","us":"media/ldoce/hwd/ame/c/valedictorian.mp3"},"oxford":{"phon":"ˌvælɪdɪkˈtɔːriən","pos":"noun","senses":[{"en":"the student who has the highest grades in a particular group of students and who gives the valedictory speech at a graduation ceremony","cn":"（毕业典礼上）致告别辞的最优生"}]}},"vagabond":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":". 流浪汉;漂泊者;无业游民","en":"A vagabond is someone who wanders from place to place and has no home or job"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has no home and travels from place to place","cn":"流浪者﹐漂泊者"}]},"vocab":{"pos":"n adj v","senses":[{"en":"A vagabond is someone who moves around a lot. Picture Boxcar Willie, bandana on a stick thrown over his shoulder, going wherever the breeze takes him."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41vagabond.mp3","us":"media/ldoce/hwd/ame/6/vagabond.mp3"},"oxford":{"phon":"ˈvæɡəbɒnd","pos":"noun","senses":[{"en":"a person who has no home or job and who travels from place to place","cn":"流浪汉；无业游民；漂泊者","ex":{"en":"beggars, rogues and vagabonds","cn":"乞丐、流氓和流浪汉"}}]}},"vacancy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（工作或职位的）空缺","en":"A vacancy is a job or position which has not been filled.","ex":{"en":"They had a short-term vacancy for a person on the foreign desk","cn":"他们在国际新闻组有一个短期的空缺职位。"}},{"pos":"N-COUNT 可数名词","cn":"（旅馆里待租的）空房","en":"If there are vacancies at a building such as a hotel, some of the rooms are available to rent.","ex":{"en":"This year hotels that usually are jammed had vacancies all summer.","cn":"今年,那些通常爆满的旅店整个夏天都有空客房。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the regular paid work that you do for an employer","cn":""},{"en":"activities that you are paid for doing – used either when you work for an employer or when you work in your own business","cn":""},{"en":"a job for which you need special education and training","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vacancy refers to something being unoccupied. If a hotel has vacancies , there are rooms available."}]},"collocations":{"phrases":["ADJ. unfilled | suitable The agency will let you know if they have any suitable vacancies. | casual, temporary | job, presidential, senate, ","VERB + VACANCY have | create, leave Her going on maternity leave will create a temporary vacancy. | fill","VACANCY + VERB arise, exist, occur A vacancy has arisen in our sales department.","PREP. ~ for a vacancy for head chef | ~ in a vacancy in the catering department"]},"media":{"uk":"media/ldoce/hwd/bre/4/vacancy0205.mp3","us":"media/ldoce/hwd/ame/4/vacancy.mp3"},"examples":[{"en":"I'm sorry, we have no vacancies.","cn":"对不起，我们这里客满。"},{"en":"the vacancy of her expression","cn":"她那茫然若失的表情"}],"oxford":{"phon":"ˈveɪkənsi","pos":"noun","senses":[{"en":"a job that is available for somebody to do","cn":"（职位的）空缺；空职；空额","g":"[countable]","lab":"especially British English","ex":{"en":"job vacancies","cn":"职位空缺"}},{"en":"a room that is available in a hotel, etc.","cn":"（旅馆等的）空房，空间","g":"[countable]","ex":{"en":"I'm sorry, we have no vacancies.","cn":"对不起，我们这里客满。"}},{"en":"the fact of a job or room being available","cn":"（指职位）空缺；空职；空额；（指房间）空房，空间","g":"[uncountable]","ex":{"en":"high office vacancy rates and stagnant housing prices","cn":"写字楼高空置率和不景气的房价"}},{"en":"lack of interest or ideas","cn":"无兴趣；无主意；空虚","g":"[uncountable]","ex":{"en":"the vacancy of her expression","cn":"她那茫然若失的表情"}}]}},"varnish":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"（涂在木头或其他材料表面的）清漆,罩光漆","en":"Varnish is an oily liquid which is painted onto wood or other material to give it a hard, clear, shiny surface.","ex":{"en":"The varnish comes in six natural wood shades.","cn":"有6种深浅不同的天然木质色泽的清漆可选。"}},{"pos":"N-SING 单数名词","cn":"（涂了清漆后的）漆面，光泽面","en":"The varnish on an object is the hard, clear, shiny surface that it has when it has been painted with varnish.","ex":{"en":"He brought out the fiddle, its varnish cracked and blistered.","cn":"他取出了小提琴，它表面的清漆已出现裂缝，还起了浮泡。"}},{"pos":"VERB 动词","cn":"给…涂上清漆","en":"If you varnish something, you paint it with varnish.","ex":{"en":"Varnish the table with two or three coats of water-based varnish","cn":"给桌子上两到三层的水性清漆。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clear liquid that is painted onto things, especially things made of wood, to protect them, or the hard shiny surface produced by this 〔","cn":"尤指刷在木制品上的〕清漆﹐罩光漆﹔光泽的表面"},{"en":"to cover something with varnish","cn":"给…涂上清漆"}]},"vocab":{"pos":"n v","senses":[{"en":"Varnish is a shiny coating that's painted on a floor or piece of furniture and then dries clear and luminous. After refinishing an old oak chair, you might apply a coat of varnish . (Just don't sit on it until it's dry.)"}]},"collocations":{"phrases":["ADJ. clear, colourless, transparent | gloss, glossy | matt (see also nail varnish)","QUANT. coat The table needed two coats of varnish.","VERB + VARNISH apply Apply the varnish evenly over the whole surface. | remove, scrape off, strip off","VARNISH + VERB dry | protect sth You need a good quality varnish to protect the timber.","VARNISH + NOUN remover"]},"media":{"uk":"media/ldoce/hwd/bre/1/varnish_n0205.mp3","us":"media/ldoce/hwd/ame/7/varnish1.mp3"},"examples":[{"en":"Her nails were varnished a brilliant shade of red.","cn":"她的指甲上涂了一层鲜亮的红指甲油。"},{"en":"( BrE ) Josie was sitting at her desk, varnishing her nails.","cn":"乔西坐在书桌旁，涂着指甲油。"}],"oxford":{"phon":"ˈvɑːnɪʃ","pos":"noun","senses":[{"en":"a liquid that is painted onto wood, metal, etc. and that forms a hard shiny surface that you can see through when it is dry","cn":"清漆","ex":{"en":"I’ll give the shelves a coat of varnish.","cn":"我会给架子涂一层清漆。"}},{"en":"to put varnish on the surface of something","cn":"给…涂清漆；上清漆；涂指甲油","lab":"British English","ex":{"en":"The doors are then stained and varnished.","cn":"这些门还要染色涂清漆。"},"pos":"verb"}]}},"vane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（靠风力或水力驱动机器的)翼，叶片，轮叶","en":"A vane is a flat blade which pushes or is pushed by wind or water, and forms part of a machine such as a fan, a windmill, or a ship's propeller."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat blade that is moved by wind or water to produce power to drive a machine 〔","cn":"靠风力或水力驱动﹑为机器产生动力的〕翼﹐叶片"}]},"vocab":{"pos":"n","senses":[{"en":"Vane is usually short for “weathervane.” If the vane on top of the building is spinning, it must be windy outside."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41vane.mp3","us":"media/ldoce/hwd/ame/1/vain.mp3"},"oxford":{"phon":"veɪn","pos":"noun","senses":[{"en":"a flat blade that is moved by wind or water and is part of the machines in a windmill, etc.","cn":"（风车等的）叶片，翼，轮叶","ex":{"en":"The windmill’s sails are wooden vanes whose angle can be adjusted from inside the mill.","cn":"风车的帆是木制叶片，其角度可以从风车内部调节。"}}]}},"variant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"变体;变种;变化形式","en":"A variant of a particular thing is something that has a different form to that thing, although it is related to it.","ex":{"en":"The quagga was a strikingly beautiful variant of the zebra","cn":"斑驴是一种极美丽的斑马变种。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one more of the same kind of thing or person","cn":""},{"en":"different ones from the ones that you already have, or that you have already mentioned","cn":""},{"en":"use this about several people or things of the same general type, when you are comparing them with each other and noticing the differences between them","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A variant is another version of something. You could say chimps and apes and gorillas are variants in the primate family."}]},"media":{"uk":"media/ldoce/hwd/bre/5/variant0205.mp3","us":"media/ldoce/hwd/ame/6/variant1.mp3"},"examples":[{"en":"This game is a variant of baseball.","cn":"这种运动是由棒球演变而来的。"},{"en":"variant forms of spelling","cn":"不同的拼写形式"}],"oxford":{"phon":"ˈveəriənt","pos":"noun","senses":[{"en":"a thing that is a slightly different form or type of something else","cn":"变种；变体；变形","ex":{"en":"This game is a variant of baseball.","cn":"这种运动是由棒球演变而来的。"}},{"en":"slightly different in form or type from something else","cn":"不同的","ex":{"en":"variant forms of spelling","cn":"不同的拼写形式"},"pos":"adjective"}]}},"vanguard":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（革命或研究的）前沿；先锋，先驱","en":"If someone is in the vanguard of something such as a revolution or an area of research, they are involved in the most advanced part of it. You can also refer to the people themselves as the vanguard.","ex":{"en":"Such thinking puts Kodak in the vanguard of a movement reshaping the computer industry","cn":"这种想法使得柯达走在了改造计算机产业运动的最前沿。"}},{"pos":"N-SING 单数名词","cn":"先头部队;尖兵","en":"The vanguard of an army is the part of it that goes into battle first.","ex":{"en":"...a force of mobile reserve units that could strike quickly and effectively at the vanguard of an invading army.","cn":"能够对入侵的先头部队进行快速有效反击的机动预备部队"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"in the most advanced position of development","cn":"在(某事物的)前沿"},{"en":"the leading position at the front of an army or group of ships moving into battle, or the soldiers who are in this position 〔","cn":"军队或舰队的〕前卫﹐前锋"}]},"vocab":{"pos":"n","senses":[{"en":"If you are in the vanguard , you're up front. It could be that you are in the vanguard of an advancing army, or in the vanguard of any movement, trend, or occupation."}]},"media":{"uk":"media/ldoce/hwd/bre/6/vanguard0205.mp3","us":"media/ldoce/hwd/ame/c/vanguard.mp3"},"examples":[{"en":"The company is proud to be in the vanguard of scientific progress.","cn":"这家公司以处于科学发展的领先地位而自豪。"},{"en":"The shop has always been in the vanguard of London fashion trends.","cn":"那家商店一直走在伦敦时尚潮流的最前沿。"}],"oxford":{"phon":"ˈvænɡɑːd","pos":"noun","senses":[{"en":"the leaders of a movement in society, for example in politics, art, industry, etc.","cn":"（政治、艺术、工业等社会活动的）领导者，先锋，先驱者","ex":{"en":"The party claimed to be the vanguard of the world revolutionary movement.","cn":"该党自称是世界革命运动的先锋队。"}},{"en":"the part of an army, etc. that is at the front when moving forward to attack the enemy","cn":"先头部队；前卫；尖兵","ex":{"en":"The army was advancing steadily and the vanguard was already at the border.","cn":"大军稳步前进，先头部队已经到了边境。"}}]}},"variance":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"（与…）不一致，相矛盾","en":"If one thing is at variance with another, the two things seem to contradict each other.","ex":{"en":"Many of his statements were at variance with the facts","cn":"他的说法有很多和事实不符。"}},{"pos":"N-VAR 可变名词","cn":"差异;不同","en":"The variance between things is the difference between them.","ex":{"en":"...the variances in the stock price.","cn":"股票价格的变化"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if two people or things are at variance with each other, they do not agree or are very different (","cn":"与某人/某事物)有分歧﹔(与某人/某事物)有冲突"},{"en":"the amount by which two or more things are different or by which they change 〔","cn":"数量的〕差异﹐不一致﹐变化幅度"},{"en":"the official permission to do something different from what is normally allowed","cn":"豁免﹐特免"}]},"vocab":{"pos":"n","senses":[{"en":"A change to the norm is called a variance . It suggests a difference or shifting away from the expected or usual, an example being snow in July, which is a variance in the weather of the United States, even in Minnesota."}]},"media":{"uk":"media/ldoce/hwd/bre/8/variance0205.mp3","us":"media/ldoce/hwd/ame/8/variance.mp3"},"examples":[{"en":"These conclusions are totally at variance with the evidence.","cn":"这些结论与证据完全相悖。"},{"en":"a note with subtle variances of pitch","cn":"音高有细微变化的音符"}],"oxford":{"phon":"ˈveəriəns","pos":"noun","senses":[{"en":"the amount by which something changes or is different from something else","cn":"变化幅度；差额","ex":{"en":"variance in temperature","cn":"温差"}}]}},"vain":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"徒劳的;无效的;不成功的","en":"A vain attempt or action is one that fails to achieve what was intended.","ex":{"en":"The drafting committee worked through the night in a vain attempt to finish on schedule","cn":"起草委员会为按计划完成草案已通宵加班，但结果仍是徒劳。"}},{"pos":"ADJ 形容词","cn":"徒然的;无望的","en":"If you describe a hope that something will happen as a vain hope, you mean that there is no chance of it happening.","ex":{"en":"He married his fourth wife, Susan, in the vain hope that she would improve his health.","cn":"他娶了第四个老婆苏珊，徒然希望她能使他健康状况好转。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自负的;虚荣的;自命不凡的","en":"If you describe someone as vain, you are critical of their extreme pride in their own beauty, intelligence, or other good qualities.","ex":{"en":"I think he is shallow, vain and untrustworthy.","cn":"我认为他浅薄虚荣，不可信任。"}},{"pos":"PHRASE 短语","cn":"徒劳;白费力气","en":"If you do something in vain, you do not succeed in achieving what you intend.","ex":{"en":"He stopped at the door, waiting in vain for her to acknowledge his presence","cn":"他在门口停住，徒然地等待她和自己打招呼。"}},{"pos":"PHRASE 短语","cn":"无用的;无意义的;无价值的","en":"If you say that something such as someone's death, suffering, or effort was in vain, you mean that it was useless because it did not achieve anything.","ex":{"en":"He wants the world to know his son did not die in vain.","cn":"他想让全世界都知道，他的儿子不是白白死去的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very pleased with what you, your family, or your country have achieved, or of something you own","cn":""},{"en":"feeling pleased because something good has happened, especially because you think you have been very clever, skilful etc","cn":""},{"en":"behaving in an unpleasant and annoying way, because you think you are better or know more than other people, and that your opinions are always right","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you spend all day admiring yourself in reflective surfaces — mirrors, pools of water, the backs of spoons — people may think you are conceited or vain ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/vain0205.mp3","us":"media/ldoce/hwd/ame/1/vain.mp3"},"examples":[{"en":"I knocked loudly in the vain hope that someone might answer.","cn":"我敲门敲得很响，希望有人应声，却是徒然。"},{"en":"They tried in vain to persuade her to go.","cn":"他们极力劝说她去，但枉费了一番口舌。"}],"oxford":{"phon":"veɪn","pos":"adjective","senses":[{"en":"that does not produce the result you want","cn":"徒劳的；枉然的；无结果的","ex":{"en":"She closed her eyes tightly in a vain attempt to hold back the tears.","cn":"她紧闭双眼，却无法忍住眼泪。"}},{"en":"too proud of your own appearance, abilities or achievements","cn":"自负的；自视过高的","lab":"disapproving","ex":{"en":"She's too vain to wear glasses.","cn":"她太爱虚荣，不肯戴眼镜。"}}]}},"valuation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"估价;估值","en":"A valuation is a judgment that someone makes about how much money something is worth.","ex":{"en":"...an independent valuation of the company","cn":"对这家公司的独立评估"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a professional judgment about how much something is worth 〔","cn":"专业的〕估价﹐估值"},{"en":"a judgment about how effective or useful a particular idea or plan will be 〔","cn":"对某个想法﹑计划的〕评价﹐评估"}]},"collocations":{"phrases":["ADJ. high, low | detailed | independent | actuarial | market | land, mortgage, property | share, stock","VERB + VALUATION carry out, do, make, prepare","VALUATION + NOUN fee, report"]},"media":{"uk":"media/ldoce/hwd/bre/5/valuation0205.mp3","us":"media/ldoce/hwd/ame/9/valuation.mp3"},"examples":[{"en":"Surveyors carried out a valuation of the property.","cn":"鉴定人员对这处房产作了估价。"},{"en":"Experts set a high valuation on the painting.","cn":"专家对这幅画估价很高。"}],"oxford":{"phon":"ˌvæljuˈeɪʃn","pos":"noun","senses":[{"en":"a professional judgement about how much money something is worth; its estimated value","cn":"（专业）估价；估定的价值；估值","ex":{"en":"Surveyors carried out a valuation of the property.","cn":"鉴定人员对这处房产做了估价。"}},{"en":"a judgement about how useful or important something is; its estimated importance","cn":"评价；评估","lab":"formal","ex":{"en":"She puts a high valuation on trust between colleagues.","cn":"她很看重同事间的信任。"}}]}},"valve":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阀;活门","en":"A valve is a device attached to a pipe or a tube which controls the flow of air or liquid through the pipe or tube."},{"pos":"N-COUNT 可数名词","cn":"（心脏的）瓣，瓣膜","en":"A valve is a small piece of tissue in your heart or in a vein which controls the flow of blood and keeps it flowing in one direction only.","ex":{"en":"He also has problems with a heart valve.","cn":"他的一个心瓣也有毛病。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of a tube or pipe that opens and shuts like a door to control the flow of liquid, gas, air etc passing through it","cn":"阀﹐活门﹔气嘴﹔瓣(膜)"},{"en":"the part on a trumpet or similar musical instrument that you press to change the sound of the note 〔","cn":"小号等乐器上的〕阀键﹐活塞"},{"en":"a closed glass tube used to control the flow of electricity in old radios, televisions etc","cn":"电子管﹐真空管"}]},"collocations":{"phrases":["ADJ. safety | non-return, one-way | drain, pressure-relief | fuel, water, etc. | heart, radiator, etc.","VERB + VALVE fit The plumber will fit some new safety valves. | open You need special tools to open the valve. | close"]},"media":{"img":["media/ldoce/img/valve.jpg","media/ldoce/img/bugle.jpg"],"uk":"media/ldoce/hwd/bre/3/valve0205.mp3","us":"media/ldoce/hwd/ame/4/valve.mp3"},"examples":[{"en":"heart valves","cn":"心脏瓣膜"}],"oxford":{"phon":"vælv","pos":"noun","senses":[{"en":"a device for controlling the flow of a liquid or gas, letting it move in one direction only","cn":"阀；阀门；活门；气门","ex":{"en":"The plumber will fit some new safety valves.","cn":"水暖工将安装几个新的安全阀。"}},{"en":"a structure in the heart or in a vein that lets blood flow in one direction only","cn":"（心脏或血管的）瓣（膜）","lab":"anatomy"},{"en":"a device in some brass musical instruments for changing the note","cn":"（铜管乐器的）阀键，活塞","lab":"music"}]}},"vaudeville":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"歌舞杂耍表演,综艺节目（尤流行于20世纪初）","en":"Vaudeville is a type of entertainment consisting of short acts such as comedy, singing, and dancing. Vaudeville was especially popular in the early part of the twentieth century.","ex":{"en":"In 1901, he broke out of vaudeville and set his sights on Broadway.","cn":"1901年，他放弃了杂耍表演，决定到百老汇发展。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of theatre entertainment, popular from the 1880s to the 1950s, in which there were many short performances of different kinds, including singing, dancing, jokes etc","cn":"歌舞杂耍表演〔盛行于19世纪80年代至20世纪50年代的一种剧院娱乐节目﹐有演唱﹑舞蹈﹑笑话等〕"}]},"vocab":{"pos":"n","senses":[{"en":"Vaudeville is a type of entertainment that mixes comedy and music in a variety show."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41vaudeville.mp3","us":"media/ldoce/hwd/ame/8/vaudeville.mp3"},"oxford":{"phon":"ˈvɔːdəvɪl","pos":"noun","senses":[{"en":"a form of theatre or television entertainment that consists of a series of short performances, such as singing, dancing and funny acts","cn":"综艺节目","lab":"North American English"},{"en":"a type of entertainment popular in the late nineteenth and early twentieth centuries, including singing, dancing and comedy","cn":"（盛行于 19 世纪末 20 世纪初的）歌舞杂耍表演","lab":"British English also"}]}}});
